:root{
  --bg:#07110e;
  --ink:#0c1c17;
  --ink-2:#10251e;
  --panel:rgba(9,23,18,.78);
  --panel-solid:#0d211a;
  --line:rgba(255,255,255,.09);
  --line-strong:rgba(255,255,255,.16);
  --text:#f3f7ed;
  --muted:#96a99f;
  --dim:#6d8178;
  --lime:#c9f46c;
  --lime-deep:#7bbf3f;
  --orange:#ffb254;
  --red:#ff6b6b;
  --blue:#70c9ff;
  --violet:#b49cff;
  --radius:18px;
  --shadow:0 22px 60px rgba(0,0,0,.42);
  --font:'Outfit',system-ui,sans-serif;
  --pixel:'Silkscreen',monospace;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--text);font-family:var(--font);-webkit-font-smoothing:antialiased;overscroll-behavior:none}
body{position:fixed;inset:0}
button,input{font-family:inherit}
button{color:inherit;cursor:pointer;border:0;background:none}
img{display:block}
kbd{font-family:var(--font);font-weight:700;font-size:10px;line-height:1;padding:4px 5px;border-radius:5px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.12);color:#c8d6cf;box-shadow:0 1px 0 rgba(0,0,0,.2)}
#app{position:absolute;inset:0;isolation:isolate;overflow:hidden}
#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;image-rendering:auto}
.world-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 42%,transparent 42%,rgba(2,10,7,.24) 100%),linear-gradient(to bottom,rgba(2,8,5,.44),transparent 14%,transparent 76%,rgba(2,8,5,.52));z-index:2}
.world-grain{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.035;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")}
.svg-defs{position:absolute;width:0;height:0;overflow:hidden}
.ico{width:20px;height:20px;display:block;flex:none}
.ico.small{width:16px;height:16px}
.glass{background:linear-gradient(145deg,rgba(17,38,30,.86),rgba(7,19,14,.8));border:1px solid var(--line);box-shadow:var(--shadow),inset 0 1px 0 rgba(255,255,255,.05);backdrop-filter:blur(16px) saturate(1.2);-webkit-backdrop-filter:blur(16px) saturate(1.2)}
.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 0 3px rgba(201,244,108,.14);animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1;box-shadow:0 0 0 3px rgba(201,244,108,.14)}50%{opacity:.6;box-shadow:0 0 0 5px rgba(201,244,108,.04)}}

/* boot */
.boot{position:absolute;inset:0;z-index:200;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 40%,#17362b 0%,#08140f 58%,#050c09 100%);transition:opacity .7s ease,visibility .7s}
.boot::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle at 20% 30%,rgba(201,244,108,.08),transparent 30%),radial-gradient(circle at 80% 70%,rgba(112,201,255,.06),transparent 35%);pointer-events:none}
.boot.hidden{opacity:0;visibility:hidden}
.boot-mark{margin-bottom:22px;filter:drop-shadow(0 16px 30px rgba(201,244,108,.16))}
.boot-title{font-family:var(--pixel);font-size:32px;letter-spacing:5px;text-shadow:0 4px 24px rgba(201,244,108,.3)}
.boot-sub{margin-top:12px;color:var(--muted);font-size:13px;letter-spacing:2px;text-transform:uppercase}
.boot-track{width:190px;height:3px;background:rgba(255,255,255,.08);border-radius:4px;margin-top:30px;overflow:hidden}
.boot-track span{display:block;height:100%;width:8%;background:linear-gradient(90deg,var(--lime),#eaffb0);border-radius:4px;transition:width .35s ease}
.brand-orb{position:relative;display:inline-flex;width:40px;height:40px;border-radius:50%;background:linear-gradient(180deg,#ff6b63 0 45%,#14201a 46% 54%,#f5f7ee 55% 100%);border:3px solid #0a1410;box-shadow:inset -4px -5px 0 rgba(0,0,0,.16),0 3px 10px rgba(0,0,0,.35);flex:none}
.brand-orb::after{content:'';position:absolute;inset:50% 0 auto;height:3px;background:#0a1410;transform:translateY(-1px)}
.brand-orb i{position:absolute;left:50%;top:50%;width:12px;height:12px;transform:translate(-50%,-50%);border-radius:50%;background:#eaf7d4;border:3px solid #0a1410;z-index:1}
.brand-orb--xl{width:76px;height:76px;border-width:5px}
.brand-orb--xl i{width:24px;height:24px;border-width:5px}
.brand-orb--xl::after{height:5px}

/* topbar */
.topbar{position:absolute;left:0;right:0;top:0;height:78px;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:0 22px;z-index:20;background:linear-gradient(to bottom,rgba(3,12,8,.88),rgba(3,12,8,.42) 62%,transparent);pointer-events:none}
.topbar>*{pointer-events:auto}
.brand{display:flex;align-items:center;gap:12px;min-width:230px}
.brand-copy{display:flex;flex-direction:column;line-height:1}
.brand-copy strong{font-family:var(--pixel);font-size:17px;letter-spacing:2.4px;text-shadow:0 2px 12px rgba(0,0,0,.5)}
.brand-copy span{margin-top:6px;font-size:8px;letter-spacing:2.5px;color:var(--muted);font-weight:700}
.zone-pill{display:flex;align-items:center;gap:12px;height:50px;padding:0 16px 0 14px;border-radius:14px;background:rgba(8,23,17,.65);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(12px);box-shadow:0 8px 30px rgba(0,0,0,.2)}
.zone-pill>.ico{color:var(--lime);width:18px;height:18px}
.zone-pill div{display:flex;flex-direction:column;min-width:132px}
.zone-kicker{font-size:7.5px;letter-spacing:1.8px;color:var(--dim);font-weight:700;margin-bottom:3px}
.zone-pill strong{font-size:13px;font-weight:700;letter-spacing:.2px}
.zone-weather{font-size:10px;color:#bed0c7;border-left:1px solid rgba(255,255,255,.1);padding-left:12px;white-space:nowrap}
.top-actions{display:flex;align-items:center;gap:9px;min-width:230px;justify-content:flex-end}
.online-pill{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--muted);padding:0 4px;white-space:nowrap}
.online-pill strong{color:#eaf3e4;font-size:11px}
.currency{display:flex;align-items:center;gap:7px;height:36px;padding:0 11px;border-radius:11px;background:rgba(8,23,17,.7);border:1px solid var(--line);font-size:12px}
.currency strong{font-weight:700}
.coin,.coin.mini{display:inline-block;width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 34% 30%,#fff2ad,#ffc94b 45%,#c88612 100%);border:1.5px solid #f7dd83;box-shadow:0 2px 5px rgba(0,0,0,.28)}
.coin.mini{width:11px;height:11px;vertical-align:-1px;margin-right:4px;border-width:1px}
.ball.mini{display:inline-block;width:12px;height:12px;border-radius:50%;background:linear-gradient(180deg,#ff6b63 0 45%,#1b241f 46% 54%,#f4f7ef 55%);border:1px solid #0a1410;vertical-align:-2px;margin-right:4px}
.icon-btn{position:relative;display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:rgba(8,23,17,.7);border:1px solid var(--line);color:#dbe7df;transition:.2s}
.icon-btn:hover{background:rgba(201,244,108,.12);border-color:rgba(201,244,108,.35);color:var(--lime);transform:translateY(-1px)}
.notif-dot{position:absolute;top:8px;right:8px;width:5px;height:5px;border-radius:50%;background:var(--orange);box-shadow:0 0 0 2px #0b1a14}

/* rails */
.left-rail{position:absolute;left:20px;top:94px;width:318px;z-index:10;display:flex;flex-direction:column;gap:10px}
.right-rail{position:absolute;right:20px;top:94px;width:286px;z-index:10;display:flex;flex-direction:column;gap:10px}
.profile-card{border-radius:16px;padding:12px 13px;display:flex;align-items:center;gap:11px;position:relative;overflow:hidden}
.profile-card::before{content:'';position:absolute;right:-20px;top:-30px;width:100px;height:100px;background:radial-gradient(circle,rgba(201,244,108,.12),transparent 70%);pointer-events:none}
.profile-avatar{position:relative;width:48px;height:48px;border-radius:13px;overflow:hidden;background:linear-gradient(160deg,#2c5f49,#17362b);border:1px solid rgba(201,244,108,.24);flex:none}
.profile-avatar canvas{width:100%;height:100%}
.profile-lv{position:absolute;right:-3px;bottom:-3px;min-width:20px;height:20px;padding:0 4px;display:grid;place-items:center;border-radius:7px;background:var(--lime);color:#16250c;font-size:9px;font-weight:800;border:2px solid #0c1c16}
.profile-main{flex:1;min-width:0}
.profile-row{display:flex;align-items:center;gap:7px}
.profile-row strong{font-size:14px;letter-spacing:.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:105px}
.rank-tag{font-family:var(--pixel);font-size:7px;padding:4px 5px;border-radius:4px;background:rgba(201,244,108,.13);color:var(--lime);border:1px solid rgba(201,244,108,.22);letter-spacing:.5px}
.xp-line{height:4px;border-radius:4px;background:rgba(255,255,255,.08);margin-top:7px;overflow:hidden}
.xp-line span{display:block;height:100%;background:linear-gradient(90deg,#9ce34f,var(--lime));border-radius:4px;box-shadow:0 0 8px rgba(201,244,108,.4)}
.profile-sub{display:flex;justify-content:space-between;margin-top:5px;font-size:8.5px;color:var(--dim);font-weight:500}
.online-mini{color:var(--lime);font-size:8px}
.profile-more{position:absolute;right:10px;top:10px;color:var(--dim);font-size:14px;letter-spacing:1px;padding:2px 4px}
.profile-more:hover{color:var(--lime)}
.quest-card{border-radius:var(--radius);padding:15px;position:relative;overflow:hidden}
.quest-card::after{content:'';position:absolute;left:0;top:18px;width:2px;height:36px;background:linear-gradient(var(--lime),transparent)}
.card-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.head-title{display:flex;align-items:center;gap:7px;font-size:8.5px;letter-spacing:1.6px;font-weight:700;color:#a9bcb3}
.quest-glyph{display:grid;place-items:center;width:16px;height:16px;border-radius:5px;background:var(--lime);color:#18300d;font-weight:800;font-size:10px;box-shadow:0 0 12px rgba(201,244,108,.25)}
.quest-chapter{font-family:var(--pixel);font-size:7px;color:var(--dim);letter-spacing:.5px}
.quest-card h3{font-size:16px;margin:4px 0 4px;letter-spacing:.1px}
.quest-card p{font-size:10.5px;line-height:1.45;color:var(--muted);margin:0 0 11px}
.quest-progress{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line);padding-top:10px}
.q-row{display:flex;align-items:center;gap:7px;font-size:9.5px;color:#bfcfc7}
.q-row span:nth-child(2){flex:1}
.q-row b{font-size:9px;color:var(--lime);font-weight:700}
.q-check{width:12px;height:12px;border-radius:50%;border:1px solid rgba(255,255,255,.22);flex:none;position:relative}
.q-row.done .q-check{background:var(--lime);border-color:var(--lime)}
.q-row.done .q-check::after{content:'✓';position:absolute;inset:0;display:grid;place-items:center;font-size:8px;color:#142509;font-weight:900}
.q-row.done span:nth-child(2){color:var(--dim);text-decoration:line-through}
.q-row.done b{color:var(--dim)}
.quest-reward{display:flex;align-items:center;gap:10px;margin-top:11px;padding-top:9px;border-top:1px dashed rgba(255,255,255,.1);font-size:8px;color:var(--dim);letter-spacing:.8px}
.quest-reward b{color:#dfe9e2;font-size:9px;font-weight:600;letter-spacing:0}
.event-card{border-radius:var(--radius);padding:12px;display:grid;grid-template-columns:52px 1fr;gap:10px;position:relative;overflow:hidden;background:linear-gradient(120deg,rgba(45,29,69,.92),rgba(8,20,15,.9));border-color:rgba(180,156,255,.22)}
.event-card::before{content:'';position:absolute;right:-20px;top:-40px;width:120px;height:120px;background:radial-gradient(circle,rgba(180,156,255,.24),transparent 70%)}
.event-art{position:relative;width:52px;height:52px;border-radius:12px;background:radial-gradient(circle at 50% 50%,rgba(180,156,255,.25),rgba(7,18,13,.4));display:grid;place-items:center;overflow:hidden}
.event-art img{width:54px;height:54px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 4px 8px rgba(0,0,0,.5));animation:eventFloat 4s ease-in-out infinite;z-index:1}
@keyframes eventFloat{0%,100%{transform:translateY(1px)}50%{transform:translateY(-3px)}}
.event-ring{position:absolute;width:42px;height:42px;border-radius:50%;border:1px solid rgba(180,156,255,.45);animation:ring 3s infinite}
.event-ring::after{content:'';position:absolute;inset:7px;border-radius:50%;border:1px solid rgba(180,156,255,.2)}
@keyframes ring{0%{transform:scale(.7);opacity:.9}100%{transform:scale(1.5);opacity:0}}
.event-spark{position:absolute;width:2px;height:2px;border-radius:50%;background:#e0d4ff;animation:twinkle 2s infinite}
.event-spark.s1{top:8px;left:8px}.event-spark.s2{top:20px;right:5px;animation-delay:.7s}.event-spark.s3{bottom:6px;left:18px;animation-delay:1.2s}
@keyframes twinkle{0%,100%{opacity:.2}50%{opacity:1}}
.event-copy{min-width:0}
.event-kicker{display:flex;align-items:center;gap:5px;font-size:7px;letter-spacing:1.4px;color:#c8b7ff;font-weight:700}
.event-kicker .live-dot{background:#c8b7ff;box-shadow:0 0 0 3px rgba(200,183,255,.12)}
.event-copy strong{display:block;font-size:11.5px;margin:3px 0 2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.event-copy p{font-size:8.5px;line-height:1.35;color:#9e94b5;margin:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.event-meta{display:flex;gap:10px;font-size:8px;color:#c8b7ff;margin-top:5px;font-weight:600}
.event-join{grid-column:1/-1;height:27px;border-radius:8px;background:rgba(180,156,255,.14);border:1px solid rgba(180,156,255,.25);color:#dcd1ff;font-size:9px;font-weight:700;letter-spacing:.5px;transition:.2s}
.event-join:hover{background:rgba(180,156,255,.24)}

/* minimap */
.minimap-card{border-radius:var(--radius);padding:11px 11px 9px;overflow:hidden}
.minimap-head{display:flex;justify-content:space-between;align-items:center;padding:1px 2px 9px}
.minimap-head>div{display:flex;flex-direction:column}
.mm-kicker{font-size:7px;letter-spacing:1.5px;color:var(--dim);font-weight:700}
.minimap-head strong{font-size:11px;margin-top:2px}
.mm-expand{width:25px;height:25px;display:grid;place-items:center;border-radius:7px;background:rgba(255,255,255,.05);color:var(--muted)}
.mm-expand .ico{width:13px;height:13px}
.mm-expand:hover{color:var(--lime);background:rgba(201,244,108,.1)}
.minimap-wrap{position:relative;height:154px;border-radius:10px;overflow:hidden;border:1px solid rgba(255,255,255,.08);background:#1b3c2b}
#minimap{width:100%;height:100%;display:block;image-rendering:pixelated}
.mm-compass{position:absolute;top:7px;right:8px;font-family:var(--pixel);font-size:8px;color:rgba(255,255,255,.72);text-shadow:0 1px 3px #000}
.mm-scan{position:absolute;inset:0;background:linear-gradient(transparent 45%,rgba(201,244,108,.07) 50%,transparent 55%);animation:scan 5s linear infinite;pointer-events:none}
@keyframes scan{from{transform:translateY(-100%)}to{transform:translateY(100%)}}
.mm-footer{display:flex;justify-content:space-between;padding:8px 3px 0;font-size:7.5px;color:var(--dim)}
.mm-footer span{display:flex;align-items:center;gap:4px}
.mm-dot{width:5px;height:5px;border-radius:50%;display:inline-block}
.mm-you{background:var(--lime);box-shadow:0 0 6px var(--lime)}
.mm-player{background:#70c9ff}.mm-wild{background:#ffb254}
.party-card{border-radius:var(--radius);padding:12px;overflow:hidden}
.party-head{margin-bottom:8px}
.link-btn{font-size:8.5px;color:var(--lime);font-weight:600;letter-spacing:.3px}
.party-rail{display:flex;flex-direction:column;gap:5px}
.party-mon{display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:9px;background:rgba(255,255,255,.035);border:1px solid transparent;position:relative;transition:.2s;cursor:pointer}
.party-mon:hover{background:rgba(255,255,255,.07)}
.party-mon.lead{border-color:rgba(201,244,108,.24);background:rgba(201,244,108,.06)}
.party-mon.lead::before{content:'';position:absolute;left:0;top:8px;bottom:8px;width:2px;border-radius:2px;background:var(--lime)}
.pm-sprite{width:31px;height:31px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 2px 3px rgba(0,0,0,.35));flex:none}
.pm-info{flex:1;min-width:0}
.pm-top{display:flex;justify-content:space-between;align-items:center;font-size:9px;margin-bottom:4px}
.pm-top strong{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pm-top span{font-size:8px;color:var(--dim);font-weight:600}
.pm-hp{height:3px;background:rgba(255,255,255,.08);border-radius:3px;overflow:hidden}
.pm-hp i{display:block;height:100%;border-radius:3px;background:var(--lime)}
.pm-hp i.mid{background:var(--orange)}.pm-hp i.low{background:var(--red)}
.pm-lv{font-family:var(--pixel);font-size:6px;color:var(--dim);margin-left:2px}
.party-foot{display:flex;justify-content:space-between;align-items:center;padding-top:8px;font-size:8px;color:var(--dim);border-top:1px solid var(--line);margin-top:8px}
.key-hint{display:flex;align-items:center;gap:4px}

/* chat */
.chat-dock{position:absolute;left:20px;bottom:18px;width:366px;height:168px;border-radius:16px;z-index:12;display:flex;flex-direction:column;overflow:hidden;transition:.3s}
.chat-dock.minimized{height:37px}
.chat-head{height:37px;display:flex;align-items:center;gap:10px;padding:0 11px;border-bottom:1px solid rgba(255,255,255,.06);flex:none}
.chat-tabs{display:flex;gap:2px}
.chat-tab{font-size:7.5px;letter-spacing:1px;font-weight:700;color:var(--dim);padding:5px 7px;border-radius:5px}
.chat-tab.active{color:var(--lime);background:rgba(201,244,108,.1)}
.chat-live{display:flex;align-items:center;gap:5px;margin-left:auto;font-size:6.5px;letter-spacing:1px;color:var(--dim)}
.chat-live .live-dot{width:4px;height:4px}
.chat-min{width:18px;height:18px;color:var(--dim);font-size:14px;line-height:1;display:grid;place-items:center;border-radius:4px}
.chat-min:hover{background:rgba(255,255,255,.06);color:var(--text)}
.chat-body{flex:1;overflow-y:auto;padding:8px 12px 4px;display:flex;flex-direction:column;gap:5px;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.1) transparent}
.chat-line{font-size:9.5px;line-height:1.4;color:#bacbc2;display:flex;gap:6px;flex-wrap:wrap;animation:slideIn .25s ease}
@keyframes slideIn{from{opacity:0;transform:translateY(3px)}to{opacity:1;transform:none}}
.chat-line .ch-name{font-weight:700;color:#8fd5a8;flex:none}
.chat-line .ch-name.you{color:var(--lime)}
.chat-line .ch-name.gm{color:var(--orange)}
.chat-line .ch-text{color:#c2d2ca;word-break:break-word}
.chat-line .ch-tag{font-size:6px;padding:2px 3px;border-radius:3px;background:rgba(112,201,255,.13);color:#7fc9ee;align-self:center}
.chat-line .ch-tag.gm{background:rgba(255,178,84,.14);color:var(--orange)}
.chat-line.system{color:var(--dim);font-style:italic}
.chat-input{display:flex;align-items:center;gap:6px;height:34px;margin:0 8px 7px;background:rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.07);border-radius:8px;padding:0 9px;flex:none}
.chat-chevron{color:var(--lime);font-size:16px}
.chat-input input{flex:1;background:none;border:0;outline:none;color:var(--text);font-size:9.5px;min-width:0}
.chat-input input::placeholder{color:#5f756b}
.chat-send{font-size:7px;letter-spacing:1px;font-weight:700;color:var(--lime);padding:4px 3px}

/* hotbar */
.hotbar-wrap{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:12;display:flex;flex-direction:column;align-items:center;gap:8px}
.interact-prompt{display:flex;align-items:center;gap:8px;height:31px;padding:0 13px 0 8px;border-radius:9px;background:rgba(9,24,18,.9);border:1px solid rgba(201,244,108,.28);box-shadow:0 8px 24px rgba(0,0,0,.4),0 0 20px rgba(201,244,108,.06);font-size:10px;font-weight:600;opacity:0;transform:translateY(5px);transition:.2s;pointer-events:none}
.interact-prompt.show{opacity:1;transform:none}
.keycap{display:grid;place-items:center;width:19px;height:19px;border-radius:5px;background:var(--lime);color:#13250b;font-size:9px;font-weight:800;box-shadow:0 2px 0 #6d9a2c}
.hotbar{display:flex;align-items:center;gap:5px;height:57px;padding:7px;border-radius:15px;background:rgba(7,20,15,.84)}
.slot{position:relative;width:45px;height:43px;border-radius:10px;display:grid;place-items:center;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.06);transition:.18s;color:#b9c9c1}
.slot:hover{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.14);transform:translateY(-2px)}
.slot.active{background:rgba(201,244,108,.12);border-color:rgba(201,244,108,.32);box-shadow:inset 0 0 14px rgba(201,244,108,.06)}
.slot .ico{width:19px;height:19px}
.slot kbd{position:absolute;right:3px;bottom:2px;font-size:6px;padding:1px 3px;background:rgba(0,0,0,.3);border-color:transparent;color:#6f857a;box-shadow:none}
.slot-count{position:absolute;left:4px;top:2px;font-size:7.5px;font-weight:700;color:#dfe9e2;text-shadow:0 1px 2px #000}
.slot-wide{width:64px;display:flex;flex-direction:row;gap:6px;padding:0 8px}
.slot-wide .emote-label{font-size:8px;color:var(--muted)}
.emote-face{font-size:16px;color:var(--lime)}
.hotbar-sep{width:1px;height:27px;background:rgba(255,255,255,.08);margin:0 1px}
.control-hint{font-size:7.5px;color:rgba(255,255,255,.42);display:flex;align-items:center;gap:4px;text-shadow:0 1px 3px #000;letter-spacing:.3px}
.control-hint kbd{font-size:6px;padding:2px 4px;background:rgba(0,0,0,.24);border-color:rgba(255,255,255,.08)}
.item-ball{width:22px;height:22px;border-radius:50%;background:linear-gradient(180deg,#ff6b63 0 45%,#1b241f 46% 54%,#f4f7ef 55%);border:1.5px solid #07110d;box-shadow:inset -2px -2px 0 rgba(0,0,0,.15),0 2px 4px rgba(0,0,0,.35);position:relative}
.item-ball::after{content:'';position:absolute;left:50%;top:50%;width:7px;height:7px;transform:translate(-50%,-50%);border-radius:50%;background:#eef7e8;border:1.5px solid #07110d}
.item-ball.great{background:linear-gradient(180deg,#5b9cff 0 45%,#1b241f 46% 54%,#f4f7ef 55%)}
.item-ball.mini-ball{width:17px;height:17px}
.item-ball.mini-ball::after{width:5px;height:5px}
.item-potion{width:18px;height:22px;border-radius:4px 4px 6px 6px;background:linear-gradient(180deg,rgba(255,255,255,.6),rgba(255,255,255,.16));border:1.5px solid rgba(255,255,255,.4);position:relative;box-shadow:0 2px 4px rgba(0,0,0,.3)}
.item-potion::before{content:'';position:absolute;left:4px;right:4px;bottom:2px;top:8px;background:linear-gradient(#ff9c9c,#ff6464);border-radius:2px 2px 4px 4px}
.item-potion::after{content:'';position:absolute;left:5px;right:5px;top:-4px;height:4px;background:#d9e6de;border-radius:2px 2px 0 0;border:1px solid rgba(0,0,0,.2)}

/* toast/banner */
.toast-stack{position:absolute;top:88px;left:50%;transform:translateX(-50%);z-index:80;display:flex;flex-direction:column;align-items:center;gap:7px;pointer-events:none;width:min(420px,90vw)}
.toast{display:flex;align-items:center;gap:10px;min-height:42px;padding:8px 15px 8px 9px;border-radius:11px;background:rgba(8,23,17,.94);border:1px solid rgba(201,244,108,.22);box-shadow:0 12px 30px rgba(0,0,0,.38);animation:toastIn .3s ease;max-width:100%}
.toast.out{animation:toastOut .3s ease forwards}
.toast-icon{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;background:rgba(201,244,108,.12);color:var(--lime);font-size:14px;flex:none}
.toast-icon.gold{background:rgba(255,178,84,.12);color:var(--orange)}
.toast-icon.purple{background:rgba(180,156,255,.14);color:#c8b7ff}
.toast strong{display:block;font-size:10.5px;line-height:1.25}
.toast span{display:block;font-size:8.5px;color:var(--muted);margin-top:1px}
@keyframes toastIn{from{opacity:0;transform:translateY(-8px) scale(.97)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-6px) scale(.98)}}
.zone-banner{position:absolute;top:23%;left:50%;transform:translate(-50%,-8px);z-index:8;text-align:center;opacity:0;pointer-events:none;transition:opacity .6s,transform .6s}
.zone-banner.show{opacity:1;transform:translate(-50%,0)}
.zone-banner::before{content:'';position:absolute;left:50%;top:50%;width:480px;height:160px;transform:translate(-50%,-50%);background:radial-gradient(ellipse,rgba(3,12,8,.54),transparent 70%);z-index:-1}
.zb-kicker{display:block;font-size:7px;letter-spacing:4px;color:var(--lime);font-weight:700;margin-bottom:6px;text-shadow:0 2px 8px #000}
.zone-banner strong{display:block;font-family:var(--pixel);font-size:26px;letter-spacing:3px;text-shadow:0 4px 20px rgba(0,0,0,.7),0 0 30px rgba(201,244,108,.1)}
.zone-banner span:last-child{display:block;font-size:10px;color:#c1d2c9;margin-top:9px;letter-spacing:1.3px;text-shadow:0 2px 8px #000}
.damage-layer{position:absolute;inset:0;pointer-events:none;z-index:70;overflow:hidden}
.dmg-float{position:absolute;font-family:var(--pixel);font-size:20px;font-weight:700;color:#fff;text-shadow:0 2px 0 #000,0 0 16px rgba(0,0,0,.6);animation:dmgFloat 1s ease-out forwards}
.dmg-float.crit{color:#ffd75e;font-size:26px}
@keyframes dmgFloat{0%{opacity:0;transform:translateY(6px) scale(.7)}15%{opacity:1;transform:translateY(-2px) scale(1.15)}100%{opacity:0;transform:translateY(-44px) scale(.9)}}

/* touch */
.touch-controls{display:none;position:absolute;inset:0;z-index:30;pointer-events:none}
.joystick{position:absolute;left:18px;bottom:18px;width:116px;height:116px;pointer-events:auto;touch-action:none}
.joy-base{position:absolute;inset:0;border-radius:50%;background:rgba(8,23,17,.44);border:1px solid rgba(255,255,255,.16);backdrop-filter:blur(5px)}
.joy-base::before,.joy-base::after{content:'';position:absolute;left:50%;top:50%;background:rgba(255,255,255,.1)}
.joy-base::before{width:1px;height:70%;transform:translate(-50%,-50%)}
.joy-base::after{height:1px;width:70%;transform:translate(-50%,-50%)}
#joyKnob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;background:rgba(201,244,108,.2);border:1.5px solid rgba(201,244,108,.65);box-shadow:0 0 20px rgba(201,244,108,.15),inset 0 0 10px rgba(201,244,108,.12)}
.touch-actions{position:absolute;right:20px;bottom:24px;display:flex;align-items:flex-end;gap:12px;pointer-events:auto}
.touch-btn{width:64px;height:64px;border-radius:50%;background:rgba(8,23,17,.66);border:1.5px solid rgba(255,255,255,.2);backdrop-filter:blur(8px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:19px;font-weight:800;color:#eef6e9;touch-action:none}
.touch-btn small{font-size:6px;letter-spacing:.5px;color:var(--muted);font-weight:600;text-transform:uppercase}
.touch-a{background:rgba(201,244,108,.16);border-color:rgba(201,244,108,.55);color:var(--lime)}
.touch-b{width:53px;height:53px;background:rgba(255,178,84,.12);border-color:rgba(255,178,84,.4)}
.touch-b .mini-ball{width:20px;height:20px}
.touch-menu{position:absolute;right:18px;top:82px;display:flex;gap:6px;pointer-events:auto}
.touch-menu button{height:31px;padding:0 11px;border-radius:8px;background:rgba(8,23,17,.66);border:1px solid rgba(255,255,255,.12);font-size:8px;letter-spacing:.4px;color:#cfded6;backdrop-filter:blur(8px)}

/* scrollbars */
*::-webkit-scrollbar{width:6px;height:6px}
*::-webkit-scrollbar-track{background:transparent}
*::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:6px}

/* ============ MODALS ============ */
.modal-root{position:absolute;inset:0;z-index:100;display:none;align-items:center;justify-content:center;padding:32px;background:rgba(3,10,7,.58);backdrop-filter:blur(5px)}
.modal-root.open{display:flex;animation:fadeIn .18s ease}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.modal{width:min(960px,100%);max-height:calc(100vh - 64px);background:linear-gradient(150deg,#11271f,#081711);border:1px solid rgba(255,255,255,.12);border-radius:22px;box-shadow:0 40px 100px rgba(0,0,0,.65);display:flex;flex-direction:column;overflow:hidden;animation:modalIn .24s cubic-bezier(.2,.8,.2,1)}
@keyframes modalIn{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
.modal.wide{width:min(1140px,100%)}
.modal.narrow{width:min(640px,100%)}
.modal-head{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--line);flex:none;background:rgba(255,255,255,.015)}
.modal-title{display:flex;align-items:center;gap:12px}
.modal-title .mt-icon{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:rgba(201,244,108,.1);color:var(--lime);border:1px solid rgba(201,244,108,.18)}
.modal-title .mt-icon.purple{background:rgba(180,156,255,.12);color:#c8b7ff;border-color:rgba(180,156,255,.2)}
.modal-title h2{font-size:20px;margin:0;letter-spacing:.1px}
.modal-title p{font-size:9.5px;color:var(--muted);margin:3px 0 0;letter-spacing:.3px}
.modal-close{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;background:rgba(255,255,255,.05);color:var(--muted);border:1px solid var(--line)}
.modal-close:hover{color:var(--text);background:rgba(255,255,255,.09)}
.modal-body{overflow-y:auto;padding:20px 22px;flex:1}
.modal-foot{padding:13px 22px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-size:9px;color:var(--dim);flex:none}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:38px;padding:0 16px;border-radius:9px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);color:var(--text);font-size:10px;font-weight:600;letter-spacing:.2px;transition:.18s}
.btn:hover{background:rgba(255,255,255,.1)}
.btn.primary{background:var(--lime);border-color:var(--lime);color:#14250b;font-weight:800;box-shadow:0 6px 18px rgba(201,244,108,.16)}
.btn.primary:hover{background:#d8ff82}
.btn.ghost{background:transparent}
.btn.purple{background:rgba(180,156,255,.16);border-color:rgba(180,156,255,.32);color:#dcd1ff}
.btn.small{height:30px;padding:0 10px;font-size:8.5px;border-radius:7px}
.btn:disabled{opacity:.45;cursor:not-allowed}

/* dex */
.dex-toolbar{display:flex;gap:10px;align-items:center;margin-bottom:14px;flex-wrap:wrap}
.search-box{display:flex;align-items:center;gap:8px;height:38px;padding:0 12px;border-radius:9px;background:rgba(0,0,0,.2);border:1px solid var(--line);flex:1;min-width:180px;color:var(--dim)}
.search-box input{flex:1;background:none;border:0;outline:none;color:var(--text);font-size:11px;min-width:0}
.search-box input::placeholder{color:var(--dim)}
.gen-chips{display:flex;gap:4px;flex-wrap:wrap}
.gen-chip{height:27px;padding:0 8px;border-radius:6px;background:rgba(255,255,255,.04);border:1px solid transparent;font-size:7.5px;font-weight:700;color:var(--dim);letter-spacing:.4px}
.gen-chip:hover{color:var(--text);background:rgba(255,255,255,.08)}
.gen-chip.active{background:rgba(201,244,108,.12);border-color:rgba(201,244,108,.25);color:var(--lime)}
.dex-stats{display:flex;gap:8px;margin-bottom:14px}
.dex-stat{flex:1;padding:9px 12px;border-radius:9px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.dex-stat span{display:block;font-size:7px;letter-spacing:1.2px;color:var(--dim);font-weight:700}
.dex-stat strong{display:block;font-size:15px;margin-top:2px}
.dex-stat strong small{font-size:9px;color:var(--dim);font-weight:500}
.dex-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:7px}
.dex-card{position:relative;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.055);padding:8px 7px 7px;cursor:pointer;transition:.18s;overflow:hidden}
.dex-card:hover{transform:translateY(-2px);background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.14)}
.dex-card.unseen{opacity:.5}
.dex-card.unseen img{filter:brightness(0) opacity(.55)}
.dex-card.caught{border-color:rgba(201,244,108,.18);background:linear-gradient(160deg,rgba(201,244,108,.07),rgba(255,255,255,.02))}
.dex-num{position:absolute;top:5px;left:7px;font-family:var(--pixel);font-size:6px;color:var(--dim)}
.dex-caught-mark{position:absolute;top:4px;right:5px;color:var(--lime);font-size:9px}
.dex-card img{width:58px;height:58px;margin:4px auto 1px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 3px 4px rgba(0,0,0,.35))}
.dex-card strong{display:block;font-size:8.5px;text-align:center;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dex-types{display:flex;justify-content:center;gap:3px;margin-top:4px}
.type-chip{display:inline-flex;align-items:center;height:13px;padding:0 4px;border-radius:3px;font-size:5.5px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#07110d}
.dex-pager{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:14px}
.dex-pager button{width:27px;height:27px;border-radius:7px;background:rgba(255,255,255,.05);border:1px solid var(--line);font-size:12px}
.dex-pager span{font-size:9px;color:var(--muted);min-width:70px;text-align:center}
.dex-detail{display:grid;grid-template-columns:220px 1fr;gap:22px}
.dex-art{position:relative;border-radius:16px;background:radial-gradient(circle at 50% 40%,rgba(201,244,108,.12),rgba(255,255,255,.02) 62%);border:1px solid var(--line);display:flex;align-items:center;justify-content:center;min-height:220px;overflow:hidden}
.dex-art::before{content:'';position:absolute;width:150px;height:150px;border-radius:50%;border:1px solid rgba(255,255,255,.06)}
.dex-art img{width:160px;height:160px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 14px 20px rgba(0,0,0,.45))}
.dex-art-num{position:absolute;left:12px;top:10px;font-family:var(--pixel);font-size:9px;color:var(--dim)}
.dex-info h3{font-size:24px;margin:0 0 4px}
.dex-info .dex-types{justify-content:flex-start;margin:7px 0 13px}
.dex-info .type-chip{height:18px;padding:0 7px;font-size:7px;border-radius:4px}
.dex-desc{font-size:10.5px;line-height:1.55;color:var(--muted);margin:0 0 15px}
.stat-bars{display:flex;flex-direction:column;gap:7px;margin-top:10px}
.stat-row{display:flex;align-items:center;gap:8px;font-size:8.5px}
.stat-row label{width:54px;color:var(--dim);font-weight:600}
.stat-row b{width:24px;text-align:right;color:#dce8e0;font-weight:700}
.stat-track{flex:1;height:5px;border-radius:4px;background:rgba(255,255,255,.07);overflow:hidden}
.stat-track i{display:block;height:100%;background:linear-gradient(90deg,#78b94b,var(--lime));border-radius:4px}
.dex-facts{display:flex;gap:8px;margin-top:13px;flex-wrap:wrap}
.dex-fact{font-size:8px;padding:4px 8px;border-radius:5px;background:rgba(255,255,255,.04);border:1px solid var(--line);color:var(--muted)}
.dex-fact b{color:var(--text);font-weight:600}

/* party modal */
.party-layout{display:grid;grid-template-columns:1fr 300px;gap:18px}
.party-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}
.party-slot{border-radius:12px;background:rgba(255,255,255,.035);border:1px solid var(--line);padding:12px;min-height:108px;position:relative;cursor:pointer;transition:.18s}
.party-slot:hover{background:rgba(255,255,255,.06)}
.party-slot.active{border-color:rgba(201,244,108,.32);background:linear-gradient(145deg,rgba(201,244,108,.08),rgba(255,255,255,.02))}
.party-slot.empty{border-style:dashed;display:flex;align-items:center;justify-content:center;color:var(--dim);font-size:10px;flex-direction:column;gap:5px}
.party-slot.empty span{font-size:24px;line-height:1}
.ps-top{display:flex;gap:10px;align-items:center}
.ps-top img{width:54px;height:54px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 4px 6px rgba(0,0,0,.4))}
.ps-name{font-size:12px;font-weight:700;display:flex;justify-content:space-between;align-items:center;gap:5px}
.ps-name span{font-size:8px;color:var(--dim);font-family:var(--pixel)}
.ps-types{display:flex;gap:3px;margin-top:4px}
.ps-hp{margin-top:9px}
.ps-hp-top{display:flex;justify-content:space-between;font-size:7.5px;color:var(--dim);margin-bottom:3px}
.ps-hp-track{height:4px;border-radius:4px;background:rgba(255,255,255,.08);overflow:hidden}
.ps-hp-track i{display:block;height:100%;background:var(--lime);border-radius:4px}
.ps-badge{position:absolute;right:8px;top:8px;font-size:6.5px;letter-spacing:.5px;color:var(--lime);background:rgba(201,244,108,.12);padding:3px 5px;border-radius:4px;font-weight:700}
.party-detail{border-radius:13px;background:rgba(0,0,0,.18);border:1px solid var(--line);padding:16px;display:flex;flex-direction:column}
.party-detail .big-sprite{width:120px;height:120px;object-fit:contain;image-rendering:pixelated;margin:0 auto;filter:drop-shadow(0 12px 18px rgba(0,0,0,.4))}
.party-detail h3{text-align:center;font-size:18px;margin:8px 0 2px}
.party-detail .pd-lv{text-align:center;font-size:8px;color:var(--dim);font-family:var(--pixel)}
.pd-moves{display:flex;flex-direction:column;gap:5px;margin-top:14px}
.pd-move{display:flex;justify-content:space-between;font-size:8.5px;padding:6px 8px;border-radius:6px;background:rgba(255,255,255,.04);border-left:2px solid var(--lime)}
.pd-move span{color:var(--dim)}
.pd-xp{margin-top:12px}
.pd-xp .ps-hp-top{font-size:7px}

/* bag */
.bag-layout{display:grid;grid-template-columns:1fr 270px;gap:18px}
.bag-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;align-content:start}
.bag-item{display:flex;align-items:center;gap:11px;padding:12px;border-radius:11px;background:rgba(255,255,255,.035);border:1px solid var(--line);cursor:pointer;transition:.18s}
.bag-item:hover{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.14)}
.bag-item .bag-icon{width:40px;height:40px;border-radius:9px;background:rgba(255,255,255,.04);display:grid;place-items:center;flex:none}
.bag-item .bag-icon .item-ball{width:24px;height:24px}
.bag-item .bag-icon .item-potion{width:21px;height:25px}
.bag-item strong{display:block;font-size:10px}
.bag-item p{font-size:8px;color:var(--dim);margin:2px 0 0;line-height:1.35}
.bag-item b{margin-left:auto;font-size:11px;color:var(--lime)}
.bag-side{border-radius:12px;background:rgba(0,0,0,.18);border:1px solid var(--line);padding:14px}
.bag-side h4{font-size:9px;letter-spacing:1px;color:var(--dim);margin:0 0 10px}
.bag-tip{font-size:9px;color:var(--muted);line-height:1.55;margin:0}
.bag-tip b{color:var(--lime)}

/* map */
.map-layout{display:grid;grid-template-columns:1fr 250px;gap:18px}
.world-map-wrap{position:relative;border-radius:14px;overflow:hidden;border:1px solid var(--line);background:#132a20;aspect-ratio:16/10}
#worldMapCanvas{width:100%;height:100%;display:block}
.map-legend{position:absolute;left:10px;bottom:10px;display:flex;gap:8px;padding:6px 9px;border-radius:7px;background:rgba(3,12,8,.72);backdrop-filter:blur(4px);font-size:7px;color:var(--muted)}
.map-legend span{display:flex;align-items:center;gap:3px}
.map-legend i{width:5px;height:5px;border-radius:50%;display:inline-block}
.map-side h4{font-size:9px;letter-spacing:1px;color:var(--dim);margin:0 0 9px}
.waypoint{width:100%;display:flex;align-items:center;gap:9px;padding:9px;border-radius:8px;background:rgba(255,255,255,.035);border:1px solid var(--line);margin-bottom:5px;text-align:left;transition:.18s}
.waypoint:hover{background:rgba(201,244,108,.08);border-color:rgba(201,244,108,.2)}
.waypoint .wp-ico{width:26px;height:26px;border-radius:7px;display:grid;place-items:center;background:rgba(201,244,108,.1);color:var(--lime);font-size:10px;flex:none}
.waypoint strong{display:block;font-size:9px}
.waypoint span{display:block;font-size:7.5px;color:var(--dim);margin-top:1px}
.waypoint em{margin-left:auto;font-style:normal;font-size:6.5px;color:var(--lime);letter-spacing:.5px}
.map-tip{margin-top:12px;padding:10px;border-radius:8px;background:rgba(112,201,255,.07);border:1px solid rgba(112,201,255,.14);font-size:8px;line-height:1.5;color:#9ab9c8}
.map-tip b{color:var(--blue)}

/* quests */
.quest-list{display:flex;flex-direction:column;gap:9px}
.quest-entry{border-radius:11px;background:rgba(255,255,255,.03);border:1px solid var(--line);padding:13px 14px;display:flex;gap:12px}
.quest-entry.main{border-color:rgba(201,244,108,.2);background:linear-gradient(120deg,rgba(201,244,108,.06),rgba(255,255,255,.02))}
.quest-entry.complete{opacity:.6}
.qe-icon{width:33px;height:33px;border-radius:9px;background:rgba(201,244,108,.12);color:var(--lime);display:grid;place-items:center;font-weight:800;font-size:13px;flex:none}
.quest-entry.side .qe-icon{background:rgba(112,201,255,.1);color:var(--blue)}
.qe-main{flex:1;min-width:0}
.qe-main h4{font-size:11px;margin:0 0 3px}
.qe-main p{font-size:8.5px;color:var(--dim);line-height:1.4;margin:0 0 6px}
.qe-objs{display:flex;flex-direction:column;gap:3px}
.qe-obj{display:flex;justify-content:space-between;font-size:8px;color:var(--muted)}
.qe-obj.done{color:var(--dim);text-decoration:line-through}
.qe-obj b{color:var(--lime);text-decoration:none}
.qe-reward{font-size:7.5px;color:var(--orange);margin-top:6px;font-weight:600}
.claim-btn{height:25px;padding:0 9px;border-radius:6px;background:var(--lime);color:#15240b;font-size:7.5px;font-weight:800;align-self:center}

/* shop */
.shop-layout{display:grid;grid-template-columns:1fr 280px;gap:18px}
.shop-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.shop-item{display:flex;gap:10px;align-items:center;padding:11px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.shop-item .bag-icon{width:37px;height:37px;display:grid;place-items:center;border-radius:8px;background:rgba(255,255,255,.04);flex:none}
.shop-item strong{display:block;font-size:9.5px}
.shop-item p{font-size:7.5px;color:var(--dim);margin:2px 0 0}
.shop-buy{margin-left:auto;display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.shop-buy span{font-size:8px;color:var(--orange);font-weight:700}
.shop-buy button{height:22px;padding:0 8px;border-radius:5px;background:rgba(201,244,108,.14);border:1px solid rgba(201,244,108,.25);color:var(--lime);font-size:7px;font-weight:700}
.shop-side{border-radius:12px;background:rgba(0,0,0,.18);border:1px solid var(--line);padding:14px}
.shop-side h4{font-size:9px;letter-spacing:1px;color:var(--dim);margin:0 0 10px}
.shop-feature{display:flex;gap:10px;align-items:center;padding:10px;border-radius:8px;background:rgba(180,156,255,.08);border:1px solid rgba(180,156,255,.15);margin-bottom:8px}
.shop-feature img{width:46px;height:46px;object-fit:contain;image-rendering:pixelated}
.shop-feature strong{display:block;font-size:9px}
.shop-feature p{font-size:7.5px;color:#a99fbe;margin:2px 0 0;line-height:1.35}
.shop-feature b{display:block;font-size:8px;color:#c8b7ff;margin-top:3px}

/* dialogue */
.dialogue-modal{width:min(720px,100%)}
.dialogue-body{padding:22px;display:flex;gap:18px;align-items:flex-start}
.dialogue-portrait{width:96px;height:96px;border-radius:18px;background:radial-gradient(circle,rgba(201,244,108,.13),rgba(255,255,255,.02));border:1px solid var(--line);display:grid;place-items:center;flex:none;position:relative;overflow:hidden}
.dialogue-portrait img{width:86px;height:86px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 6px 10px rgba(0,0,0,.4))}
.dialogue-copy{flex:1}
.dialogue-name{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:700}
.dialogue-name span{font-size:7px;color:var(--lime);background:rgba(201,244,108,.1);padding:3px 5px;border-radius:4px;letter-spacing:.6px}
.dialogue-text{font-size:11.5px;line-height:1.6;color:#d3e0d8;margin:9px 0 0;min-height:52px}
.dialogue-actions{display:flex;justify-content:flex-end;gap:7px;padding:0 22px 18px}
.dialogue-choice{display:flex;flex-direction:column;gap:6px;margin-top:13px}
.dialogue-choice button{text-align:left;padding:9px 11px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid var(--line);font-size:9.5px}
.dialogue-choice button:hover{border-color:rgba(201,244,108,.3);background:rgba(201,244,108,.07);color:var(--lime)}

/* social */
.social-layout{display:grid;grid-template-columns:1fr 280px;gap:18px}
.social-list{display:flex;flex-direction:column;gap:6px}
.social-player{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:9px;background:rgba(255,255,255,.03);border:1px solid var(--line)}
.sp-avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-size:11px;font-weight:800;color:#102218;flex:none;position:relative}
.sp-avatar::after{content:'';position:absolute;right:-1px;bottom:-1px;width:7px;height:7px;border-radius:50%;background:var(--lime);border:2px solid #0d1f18}
.sp-info{flex:1}
.sp-info strong{font-size:9.5px;display:flex;gap:5px;align-items:center}
.sp-info span{font-size:7.5px;color:var(--dim);display:block;margin-top:1px}
.sp-tag{font-size:6px;padding:2px 4px;border-radius:3px;background:rgba(201,244,108,.1);color:var(--lime);font-weight:700}
.sp-action{font-size:7.5px;color:var(--muted);border:1px solid var(--line);padding:5px 8px;border-radius:5px;background:rgba(255,255,255,.03)}
.sp-action:hover{color:var(--lime);border-color:rgba(201,244,108,.2)}
.social-side{border-radius:12px;background:rgba(0,0,0,.18);border:1px solid var(--line);padding:14px}
.social-side h4{font-size:9px;letter-spacing:1px;color:var(--dim);margin:0 0 10px}
.shard-stat{display:flex;justify-content:space-between;font-size:8.5px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.05)}
.shard-stat span{color:var(--dim)}.shard-stat b{color:var(--lime)}
.shard-note{font-size:8px;line-height:1.5;color:var(--dim);margin:10px 0 0}
.invite-box{margin-top:12px;padding:10px;border-radius:8px;background:rgba(112,201,255,.06);border:1px solid rgba(112,201,255,.14)}
.invite-box strong{font-size:8px;color:var(--blue);display:block;margin-bottom:3px}
.invite-box p{font-size:7.5px;color:#8eaab7;line-height:1.4;margin:0 0 7px}
.invite-box input{width:100%;height:25px;border-radius:5px;border:1px solid var(--line);background:rgba(0,0,0,.2);color:var(--text);font-size:7.5px;padding:0 7px}

/* settings */
.settings-list{display:flex;flex-direction:column;gap:8px}
.setting-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 12px;border-radius:9px;background:rgba(255,255,255,.03);border:1px solid var(--line)}
.setting-row strong{font-size:9.5px;display:block}
.setting-row p{font-size:7.5px;color:var(--dim);margin:2px 0 0}
.toggle{width:35px;height:20px;border-radius:20px;background:rgba(255,255,255,.1);position:relative;flex:none;transition:.2s}
.toggle::after{content:'';position:absolute;left:3px;top:3px;width:14px;height:14px;border-radius:50%;background:#8da197;transition:.2s}
.toggle.on{background:rgba(201,244,108,.28)}
.toggle.on::after{left:18px;background:var(--lime)}

/* battle */
.battle-root{position:absolute;inset:0;z-index:150;display:none;overflow:hidden}
.battle-root.open{display:block}
.battle-scene{position:absolute;inset:0;background:#10281f;overflow:hidden}
.battle-sky{position:absolute;inset:0;background:linear-gradient(180deg,#9fd6c1 0%,#d7ebbe 48%,#8fbb72 49%,#5f9250 100%);transition:.4s}
.battle-scene[data-biome="forest"] .battle-sky{background:linear-gradient(180deg,#7fb79e 0%,#c5ddac 45%,#5e8a50 46%,#3e633e 100%)}
.battle-scene[data-biome="lake"] .battle-sky{background:linear-gradient(180deg,#9cd3e6 0%,#d3ebda 46%,#7bb1a5 47%,#3f7c79 100%)}
.battle-scene[data-biome="volcano"] .battle-sky{background:linear-gradient(180deg,#e8a36b 0%,#e6c28f 44%,#8f5d42 45%,#55372c 100%)}
.battle-scene[data-biome="snow"] .battle-sky{background:linear-gradient(180deg,#b7d8ea 0%,#eef8f2 46%,#b4d4d7 47%,#6f9aa7 100%)}
.battle-scene[data-biome="swamp"] .battle-sky{background:linear-gradient(180deg,#829c8d 0%,#bcc7a2 46%,#6f8057 47%,#43543b 100%)}
.battle-scene[data-biome="peak"] .battle-sky{background:linear-gradient(180deg,#a8c9d9 0%,#e3e6cc 44%,#8a9a86 45%,#4e5d52 100%)}
.battle-sun{position:absolute;width:180px;height:180px;border-radius:50%;background:radial-gradient(circle,rgba(255,246,186,.7),rgba(255,231,144,.15) 50%,transparent 70%);top:4%;right:12%}
.battle-cloud{position:absolute;height:36px;border-radius:40px;background:rgba(255,255,255,.4);filter:blur(3px)}
.battle-cloud.c1{width:180px;top:12%;left:10%;animation:cloud 38s linear infinite}
.battle-cloud.c2{width:120px;top:20%;left:58%;opacity:.6;animation:cloud 52s linear infinite reverse}
@keyframes cloud{from{transform:translateX(-80px)}to{transform:translateX(220px)}}
.battle-hills{position:absolute;left:-5%;right:-5%;bottom:32%;height:24%;background:#73945e;clip-path:polygon(0 60%,12% 25%,25% 52%,40% 10%,55% 45%,70% 18%,84% 50%,100% 22%,100% 100%,0 100%);opacity:.45}
.battle-ground{position:absolute;left:-5%;right:-5%;bottom:0;height:38%;background:radial-gradient(ellipse at 50% 0%,#a4c273,#5e8f51 40%,#3d6841 100%)}
.battle-ground::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle at 10% 20%,rgba(255,255,255,.12) 1px,transparent 1px),radial-gradient(circle at 70% 60%,rgba(0,0,0,.1) 1px,transparent 1px);background-size:33px 29px,41px 37px;opacity:.5}
.battle-platform{position:absolute;border-radius:50%;background:radial-gradient(ellipse,rgba(64,102,54,.55),rgba(64,102,54,0) 68%);border:1px solid rgba(255,255,255,.08)}
.enemy-platform{width:290px;height:76px;right:14%;top:31%}
.ally-platform{width:330px;height:90px;left:12%;bottom:24%}
.battle-topbar{position:absolute;top:0;left:0;right:0;display:flex;justify-content:space-between;align-items:center;padding:18px 24px;z-index:3;background:linear-gradient(to bottom,rgba(4,14,9,.42),transparent)}
.battle-mode{display:flex;align-items:center;gap:8px;font-family:var(--pixel);font-size:8px;letter-spacing:1.5px;color:#f0f8e7;text-shadow:0 2px 4px rgba(0,0,0,.4)}
.battle-mode .dot{width:6px;height:6px;border-radius:50%;background:#ff6b6b;box-shadow:0 0 8px #ff6b6b}
.battle-exit{width:32px;height:32px;border-radius:8px;background:rgba(4,14,9,.3);border:1px solid rgba(255,255,255,.2);color:#fff;display:grid;place-items:center;backdrop-filter:blur(5px)}
.enemy-mon{position:absolute;right:12%;top:12%;width:320px;z-index:2;animation:enemyIn .55s cubic-bezier(.2,.8,.2,1)}
@keyframes enemyIn{from{opacity:0;transform:translate(70px,-20px)}to{opacity:1;transform:none}}
.enemy-mon img{width:210px;height:210px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 20px 22px rgba(0,0,0,.32));display:block;margin:0 auto;animation:monFloat 3s ease-in-out infinite}
@keyframes monFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
.enemy-mon img.hit{animation:monHit .35s}
@keyframes monHit{0%,100%{transform:translateX(0);filter:none}25%{transform:translateX(12px);filter:brightness(2.4)}50%{transform:translateX(-8px);filter:brightness(.6)}75%{transform:translateX(5px)}}
.ally-mon{position:absolute;left:11%;bottom:14%;width:340px;z-index:2;animation:allyIn .55s cubic-bezier(.2,.8,.2,1)}
@keyframes allyIn{from{opacity:0;transform:translate(-60px,30px)}to{opacity:1;transform:none}}
.ally-mon img{width:260px;height:260px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 24px 26px rgba(0,0,0,.34));display:block;margin:0 auto;animation:monFloat 3.4s ease-in-out infinite .3s;transform:scaleX(-1)}
.ally-mon img.hit{animation:monHit .35s}
.battle-hud{position:absolute;z-index:3;min-width:260px;padding:11px 13px;border-radius:12px;background:rgba(5,18,12,.82);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(8px);box-shadow:0 10px 30px rgba(0,0,0,.3)}
.enemy-hud{left:6%;top:8%}
.ally-hud{right:8%;bottom:36%}
.hud-top{display:flex;justify-content:space-between;align-items:center;gap:14px}
.hud-top strong{font-size:15px;letter-spacing:.3px}
.hud-top span{font-family:var(--pixel);font-size:7px;color:#c5d7cd}
.hud-types{display:flex;gap:4px;margin-top:3px}
.hud-types .type-chip{height:14px;font-size:5.5px}
.hud-hp{margin-top:8px}
.hud-hp-top{display:flex;justify-content:space-between;font-size:7.5px;color:#a9bdb3;margin-bottom:4px}
.hp-track{height:7px;border-radius:4px;background:rgba(255,255,255,.12);overflow:hidden;border:1px solid rgba(0,0,0,.2)}
.hp-track i{display:block;height:100%;background:linear-gradient(90deg,#8fe34a,var(--lime));border-radius:3px;transition:width .55s cubic-bezier(.2,.8,.2,1)}
.hp-track i.mid{background:linear-gradient(90deg,#ff9a3d,var(--orange))}
.hp-track i.low{background:linear-gradient(90deg,#ff4d4d,#ff8a8a)}
.hud-sub{display:flex;justify-content:space-between;font-size:7px;color:#91a69b;margin-top:5px}
.battle-log{position:absolute;left:50%;top:43%;transform:translateX(-50%);z-index:4;padding:7px 18px;border-radius:20px;background:rgba(4,14,9,.62);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(7px);font-size:10px;font-weight:500;color:#f0f7ea;white-space:nowrap;max-width:80vw;overflow:hidden;text-overflow:ellipsis;transition:.2s}
.battle-log.pop{animation:logPop .25s}
@keyframes logPop{0%{transform:translateX(-50%) scale(.95);opacity:.5}100%{transform:translateX(-50%) scale(1);opacity:1}}
.battle-panel{position:absolute;left:0;right:0;bottom:0;z-index:5;display:grid;grid-template-columns:1fr 370px;gap:0;background:rgba(6,19,13,.94);border-top:1px solid rgba(255,255,255,.13);backdrop-filter:blur(18px);min-height:184px}
.battle-menu{padding:16px 18px;display:grid;grid-template-columns:1fr 1fr;gap:7px;align-content:center}
.move-btn{position:relative;height:58px;border-radius:9px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.09);padding:8px 11px;text-align:left;transition:.16s;overflow:hidden}
.move-btn:hover{background:rgba(255,255,255,.085);border-color:rgba(255,255,255,.2);transform:translateY(-1px)}
.move-btn:disabled{opacity:.35}
.move-btn::after{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--mt,#9fa)}
.move-name{display:flex;justify-content:space-between;align-items:center;font-size:10.5px;font-weight:600}
.move-name span{font-size:7px;color:#8fa49a;font-weight:500}
.move-meta{display:flex;align-items:center;gap:7px;margin-top:6px}
.move-meta .type-chip{height:13px;font-size:5.5px}
.move-meta span{font-size:7px;color:#73887e}
.move-meta b{font-size:7px;color:#a9bbb2;margin-left:auto;font-weight:500}
.battle-actions{border-left:1px solid rgba(255,255,255,.09);padding:14px 16px;display:flex;flex-direction:column;gap:7px;justify-content:center}
.battle-actions h4{font-size:8px;letter-spacing:1.3px;color:#7d9388;margin:0 0 3px;font-weight:700}
.action-btn{height:38px;border-radius:8px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;gap:9px;padding:0 11px;font-size:9.5px;font-weight:600;transition:.16s}
.action-btn:hover{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.2)}
.action-btn .a-ico{width:23px;height:23px;border-radius:6px;display:grid;place-items:center;background:rgba(201,244,108,.12);color:var(--lime);font-size:10px;flex:none}
.action-btn .a-ico.orange{background:rgba(255,178,84,.12);color:var(--orange)}
.action-btn .a-ico.blue{background:rgba(112,201,255,.12);color:var(--blue)}
.action-btn kbd{margin-left:auto}
.action-btn.run{color:#d4b0b0;border-color:rgba(255,107,107,.16)}
.action-btn.run .a-ico{background:rgba(255,107,107,.12);color:var(--red)}
.battle-hint{font-size:6.5px;color:#5c7368;text-align:center;margin-top:4px}
.battle-bag{position:absolute;inset:0;z-index:8;background:rgba(4,13,9,.78);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;padding:30px}
.battle-bag.open{display:flex;animation:fadeIn .15s}
.battle-bag-inner{width:min(540px,100%);background:linear-gradient(150deg,#12281f,#091811);border:1px solid var(--line-strong);border-radius:16px;padding:17px;box-shadow:0 30px 80px rgba(0,0,0,.5)}
.battle-bag-inner h3{font-size:14px;margin:0 0 3px}
.battle-bag-inner p{font-size:8px;color:var(--dim);margin:0 0 12px}
.battle-bag-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.bag-choice{padding:10px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid var(--line);display:flex;align-items:center;gap:8px;font-size:9px}
.bag-choice:hover{background:rgba(201,244,108,.08);border-color:rgba(201,244,108,.2)}
.bag-choice b{margin-left:auto;color:var(--lime);font-size:8px}
.catch-overlay{position:absolute;inset:0;z-index:10;display:none;align-items:center;justify-content:center;pointer-events:none}
.catch-overlay.show{display:flex}
.catch-ball{position:absolute;width:30px;height:30px;border-radius:50%;background:linear-gradient(180deg,#ff6b63 0 45%,#1b241f 46% 54%,#f4f7ef 55%);border:2px solid #07110d;box-shadow:0 6px 16px rgba(0,0,0,.4);animation:ballThrow 1.1s cubic-bezier(.2,.7,.3,1) forwards;left:22%;bottom:34%}
@keyframes ballThrow{0%{transform:translate(0,0) rotate(0);opacity:0}15%{opacity:1}55%{transform:translate(62vw,-26vh) rotate(720deg)}70%{transform:translate(62vw,-20vh) rotate(760deg)}100%{transform:translate(62vw,-15vh) rotate(760deg)}}
.catch-burst{position:absolute;left:50%;top:35%;width:160px;height:160px;border-radius:50%;border:2px solid rgba(255,255,255,.6);opacity:0;transform:translate(-50%,-50%) scale(.2)}
.catch-overlay.show .catch-burst{animation:burst .8s 1s forwards}
@keyframes burst{0%{opacity:1;transform:translate(-50%,-50%) scale(.2)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.7)}}
.catch-label{position:absolute;bottom:29%;left:50%;transform:translateX(-50%);font-family:var(--pixel);font-size:13px;color:#fff;text-shadow:0 3px 10px #000;opacity:0}
.catch-overlay.show .catch-label{animation:catchLabel 1s 1.1s forwards}
@keyframes catchLabel{to{opacity:1}}
.battle-result{position:absolute;inset:0;z-index:12;background:rgba(3,11,7,.72);backdrop-filter:blur(7px);display:none;align-items:center;justify-content:center}
.battle-result.show{display:flex;animation:fadeIn .25s}
.result-card{width:min(430px,90%);border-radius:18px;background:linear-gradient(155deg,#173326,#091811);border:1px solid rgba(201,244,108,.24);box-shadow:0 30px 80px rgba(0,0,0,.55);padding:22px;text-align:center}
.result-emblem{width:58px;height:58px;margin:0 auto 10px;border-radius:50%;background:rgba(201,244,108,.12);display:grid;place-items:center;color:var(--lime);border:1px solid rgba(201,244,108,.25);font-size:24px}
.result-card h3{font-size:21px;margin:0 0 5px}
.result-card p{font-size:10px;color:var(--muted);line-height:1.5;margin:0 0 14px}
.result-stats{display:flex;justify-content:center;gap:18px;padding:11px;border-radius:9px;background:rgba(0,0,0,.2);margin-bottom:14px}
.result-stats div{text-align:center}
.result-stats span{display:block;font-size:7px;color:var(--dim);letter-spacing:.8px}
.result-stats strong{display:block;font-size:13px;color:var(--lime);margin-top:2px}
.result-card .btn{width:100%}

/* zone title colors etc */
.hidden{display:none!important}

