  /* ---------------- UI: settings ---------------- */
  openSettings(){
    this.openModal({
      title:'Settings', subtitle:'Make Terraverse feel like home', icon:'⚙', narrow:true,
      body:`<div class="settings-list">
        <div class="setting-row"><div><strong>Sound & music</strong><p>Ambient field music, battle themes and effects.</p></div><button class="toggle ${this.settings.sound?'on':''}" data-setting="sound"></button></div>
        <div class="setting-row"><div><strong>Ambient particles</strong><p>Pollen, snow, embers and fireflies.</p></div><button class="toggle ${this.settings.particles?'on':''}" data-setting="particles"></button></div>
        <div class="setting-row"><div><strong>Day / night tint</strong><p>Warm evenings and deep blue nights.</p></div><button class="toggle ${this.settings.dayNight?'on':''}" data-setting="dayNight"></button></div>
        <div class="setting-row"><div><strong>Trainer profile</strong><p>${escapeHtml(this.player.name)} · Level ${this.player.level} · ${this.playerId}</p></div><span class="rank-tag">${this.player.rank}</span></div>
        <div class="setting-row"><div><strong>Reset adventure</strong><p>Erase this save and begin again in Verdant Hollow.</p></div><button class="btn small" id="resetSave" style="color:#ff8b8b;border-color:rgba(255,107,107,.2)">Reset</button></div>
      </div>`,
      footer:`<span>Terraverse v1.0 · Shard 07 · ${this.zone.name}</span><span>Autosaved</span>`,
      onMount:(root)=>{
        root.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{
          const k=b.dataset.setting; this.settings[k]=!this.settings[k]; b.classList.toggle('on',this.settings[k]);
          if(k==='sound'){ this.audio.init(); this.audio.enabled=this.settings.sound; if(this.audio.master) this.audio.master.gain.value=this.settings.sound?.13:0; }
          this.save();
        });
        root.querySelector('#resetSave').onclick=()=>{
          if(root.querySelector('#resetSave').dataset.confirm==='1') this.reset();
          else { root.querySelector('#resetSave').dataset.confirm='1'; root.querySelector('#resetSave').textContent='Really reset?'; }
        };
      }
    });
  }

  /* ---------------- UI: emotes ---------------- */
  openEmotes(){
    const emotes=[['👋','Wave'],['🎉','Cheer'],['💃','Dance'],['✨','Sparkle'],['❤️','Heart'],['💪','Flex']];
    this.openModal({
      title:'Emotes', subtitle:'A little personality goes a long way', icon:'☺', narrow:true,
      body:`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${emotes.map(([e,n])=>`<button class="btn" data-emote="${n}" style="height:76px;flex-direction:column;font-size:26px;gap:4px">${e}<span style="font-size:8px;color:#96a99f">${n}</span></button>`).join('')}</div>`,
      footer:`<span>Emotes appear in local chat.</span><span><kbd>X</kbd> close</span>`,
      onMount:(root)=>{
        root.querySelectorAll('[data-emote]').forEach(b=>b.onclick=()=>{
          const n=b.dataset.emote;
          this.addChat('local','You',`${n.toLowerCase()}s ${n==='Wave'?'👋':'✨'}`,'');
          this.broadcast({type:'chat',channel:'local',name:this.player.name,text:`${n.toLowerCase()}s ${n==='Wave'?'👋':'✨'}`,id:this.playerId});
          this.closeModal(); this.toast('Emote sent',`${n}!`,'purple');
        });
      }
    });
  }

  /* ---------------- UI: raid ---------------- */
  openRaid(){
    const done=this.quests.raid.claimed;
    this.openModal({
      title:'Sky Serpent Sighting', subtitle:'World event · Victory Peak · 47 trainers gathered', icon:'◆', narrow:true,
      body:`<div style="text-align:center"><div style="position:relative;height:210px;display:grid;place-items:center;background:radial-gradient(circle,rgba(180,156,255,.18),transparent 65%);border-radius:16px;border:1px solid rgba(180,156,255,.18);overflow:hidden;margin-bottom:14px">
        <img src="${spriteUrl(384)}" alt="Rayquaza" style="width:170px;height:170px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 16px 24px rgba(0,0,0,.45))">
        <span style="position:absolute;bottom:14px;font-family:Silkscreen;font-size:9px;letter-spacing:2px;color:#d8cbff">LEGENDARY RAID · Lv. ${Math.max(18,this.player.level+4)}</span>
      </div>
      <p style="font-size:10px;line-height:1.6;color:#a9bcb3;max-width:440px;margin:0 auto 14px">Rayquaza has descended through the cloudbreak above Victory Peak. The air crackles with dragon energy. Join the gathered trainers and drive the sky serpent back into the stratosphere.</p>
      <div style="display:flex;justify-content:center;gap:18px;padding:11px;border-radius:9px;background:rgba(0,0,0,.18);margin-bottom:14px">
        <div style="text-align:center"><span style="display:block;font-size:7px;color:#6d8178;letter-spacing:1px">TRAINERS</span><strong style="font-size:13px;color:#c8b7ff">47 / 50</strong></div>
        <div style="text-align:center"><span style="display:block;font-size:7px;color:#6d8178;letter-spacing:1px">TIME LEFT</span><strong style="font-size:13px;color:#c8b7ff">${$('#eventTimer').textContent}</strong></div>
        <div style="text-align:center"><span style="display:block;font-size:7px;color:#6d8178;letter-spacing:1px">REWARD</span><strong style="font-size:13px;color:#c8b7ff">2,500c</strong></div>
      </div>
      <button class="btn purple" id="joinRaid" style="width:100%;height:44px" ${done?'disabled':''}>${done?'Raid already cleared':'Join the raid'}</button>
      <p style="font-size:7.5px;color:#6d8178;margin-top:9px">Your team will be healed after the encounter. Raid battles cannot be fled.</p></div>`,
      footer:`<span>Sky Festival world event</span><span><kbd>Esc</kbd> close</span>`,
      onMount:(root)=>{
        root.querySelector('#joinRaid').onclick=()=>{
          if(done) return;
          this.closeModal();
          this.battle.open(null,{raid:true,zone:ZONE_BY_ID.peak});
        };
      }
    });
  }

  /* ---------------- UI: dialogue ---------------- */
  openDialogue(npc){
    let index=0;
    const render=()=>{
      const line=npc.lines[index];
      this.openModal({
        title:'', subtitle:'', icon:'', narrow:true, body:'', onMount:()=>{}
      });
      // Custom shell for a more intimate conversation layout.
      const root=$('#modalRoot');
      root.innerHTML=`<div class="modal narrow dialogue-modal">
        <div class="dialogue-body">
          <div class="dialogue-portrait">${npc.sprite?`<img src="${spriteUrl(npc.sprite)}" alt="">`:`<span style="font-size:36px">✎</span>`}</div>
          <div class="dialogue-copy"><div class="dialogue-name">${escapeHtml(npc.name)} <span>${escapeHtml(npc.role)}</span></div><p class="dialogue-text">${escapeHtml(line)}</p></div>
        </div>
        <div class="dialogue-actions" id="dialogueActions"></div>
      </div>`;
      root.classList.add('open'); this.modalOpen=true;
      root.onclick=e=>{ if(e.target===root) this.closeModal(); };
      const actions=root.querySelector('#dialogueActions');
      const next=document.createElement('button'); next.className='btn primary'; next.textContent=index<npc.lines.length-1?'Continue':'Close';
      next.onclick=()=>{ this.audio.sfx('click'); if(index<npc.lines.length-1){ index++; render(); } else finish(); };
      actions.appendChild(next);
      const finish=()=>{
        const type=npc.dialogueType;
        if(type==='professor'){
          const first=this.quests.main.talk===0;
          if(first){
            this.quests.main.talk=1; this.bag.pokeball+=10; this.addTrainerXp(250); this.audio.sfx('coin');
            this.toast('Field supplies received','+10 Poké Balls · quest updated','gold');
            this.updateHud(); this.save();
          }
          this.closeModal(); this.openDex();
        } else if(type==='heal'){
          this.party.forEach(healMon); this.audio.sfx('heal');
          this.toast('Your team is fully healed','Nurse Joy gives you a warm smile.','gold');
          this.renderParty(); this.updateHud(); this.save(); this.closeModal();
        } else if(type==='shop'){
          this.openShop();
        } else if(type==='rival'||type==='trainer'){
          this.closeModal();
          if(npc.team) setTimeout(()=>this.battle.open(null,{trainer:npc}),250);
        } else this.closeModal();
      };
      if(index===npc.lines.length-1){
        const type=npc.dialogueType;
        if(type==='heal'){ const b=document.createElement('button'); b.className='btn'; b.textContent='Heal my team'; b.onclick=()=>{this.party.forEach(healMon);this.audio.sfx('heal');this.toast('Team healed','All Pokémon are at full HP.','gold');this.renderParty();this.updateHud();this.closeModal();this.save();}; actions.prepend(b); }
        if(type==='shop'){ const b=document.createElement('button'); b.className='btn'; b.textContent='Browse wares'; b.onclick=()=>this.openShop(); actions.prepend(b); }
        if(type==='rival'||type==='trainer'){ const b=document.createElement('button'); b.className='btn'; b.textContent='Battle'; b.onclick=()=>{this.closeModal();this.battle.open(null,{trainer:npc});}; actions.prepend(b); }
        if(type==='professor'){ const b=document.createElement('button'); b.className='btn'; b.textContent='View Pokédex'; b.onclick=()=>{this.closeModal();this.openDex();}; actions.prepend(b); }
      }
    };
    render();
  }

  /* ---------------- chat helpers ---------------- */
  // Reserved for future features.
}

function escapeHtml(s=''){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function bagIcon(k){
  if(k==='pokeball'||k==='greatball'||k==='ultraball') return `<span class="item-ball ${k==='greatball'?'great':''}" style="${k==='ultraball'?'background:linear-gradient(180deg,#ffd54d 0 45%,#1b241f 46% 54%,#f4f7ef 55%)':''}"></span>`;
  if(k==='potion'||k==='superpotion') return '<span class="item-potion"></span>';
  if(k==='berry') return '<span style="font-size:20px">🍒</span>';
  if(k==='revive') return '<span style="font-size:18px;color:#c9f46c">✚</span>';
  return '<span style="font-size:18px">✦</span>';
}

import { Game } from './game.js';

async function boot(){
  const bar=document.getElementById('bootBar');
  let p=8;
  const tick=setInterval(()=>{ p=Math.min(92,p+Math.random()*14); bar.style.width=p+'%'; },180);
  try{
    const res=await fetch('./assets/data/pokemon.json');
    if(!res.ok) throw new Error('Could not load the Pokédex data.');
    const data=await res.json();
    p=96; bar.style.width='96%';
    const game=new Game(data);
    window.terraverse=game;
    game.init();
    bar.style.width='100%';
    clearInterval(tick);
    document.documentElement.classList.add('ready');
  }catch(err){
    clearInterval(tick);
    console.error(err);
    document.getElementById('boot').innerHTML=`<div class="boot-mark"><span class="brand-orb brand-orb--xl"><i></i></span></div><div class="boot-title">TERRAVERSE</div><div class="boot-sub" style="color:#ff9b9b;text-transform:none;letter-spacing:.4px">The wilds could not be reached. ${String(err.message||err)}</div>`;
  }
}
boot();

