228:   bindJoystick(){
229:     const joy=$('#joystick'), knob=$('#joyKnob');
230:     let id=null;
231:     const update=(e)=>{
232:       const r=joy.getBoundingClientRect();
233:       let dx=e.clientX-(r.left+r.width/2), dy=e.clientY-(r.top+r.height/2);
234:       const max=r.width*.32, len=Math.hypot(dx,dy);
235:       if(len>max){ dx=dx/len*max; dy=dy/len*max; }
236:       knob.style.transform=`translate(${dx}px,${dy}px)`;
237:       this.touch.x=dx/max; this.touch.y=dy/max; this.touch.active=true;
238:     };
239:     joy.addEventListener('pointerdown',e=>{ id=e.pointerId; joy.setPointerCapture(id); update(e); e.preventDefault(); });
240:     joy.addEventListener('pointermove',e=>{ if(e.pointerId===id) update(e); });
241:     const end=e=>{ if(e.pointerId!==id) return; id=null; this.touch.active=false; this.touch.x=0; this.touch.y=0; knob.style.transform=''; };
242:     joy.addEventListener('pointerup',end); joy.addEventListener('pointercancel',end);
243:   }
