245:   onKeyDown(e){
246:     if(this.battle.active) return;
247:     const tag=document.activeElement?.tagName;
248:     if(tag==='INPUT'||tag==='TEXTAREA'){
249:       if(e.key==='Escape') document.activeElement.blur();
250:       return;
251:     }
252:     const k=e.key.toLowerCase();
253:     if(e.key==='Escape'){
254:       if(this.modalOpen) this.closeModal();
255:       else if($('#chatDock').classList.contains('minimized')) $('#chatDock').classList.remove('minimized');
256:       return;
257:     }
258:     if(this.modalOpen) return;
259:     if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift'].includes(k)){
260:       this.keys.add(k); if(k===' '||k.startsWith('arrow')) e.preventDefault();
261:     }
262:     if(e.repeat) return;
263:     if(k==='e'||k===' '){ this.interact(); e.preventDefault(); }
264:     else if(k==='m') this.openMap();
265:     else if(k==='d') this.openDex();
266:     else if(k==='p') this.openParty(0);
267:     else if(k==='b') this.openBag();
268:     else if(k==='j') this.openQuests();
269:     else if(k==='o') this.openSocial();
270:     else if(k==='x') this.openEmotes();
271:     else if(k==='enter'){ $('#chatInput').focus(); e.preventDefault(); }
272:     else if(k==='1') this.selectBall('pokeball');
273:     else if(k==='2') this.selectBall('greatball');
274:     else if(k==='3') this.usePotionOnLead();
275:   }
