277:   onCanvasClick(e){
278:     if(this.modalOpen||this.battle.active||this.paused) return;
279:     const wx=(e.clientX+this.cam.x)/T, wy=(e.clientY+this.cam.y)/T;
280:     let best=null,bd=2.2;
281:     for(const w of this.wilds){ const d=Math.hypot(w.x-wx,w.y-wy); if(d<bd){bd=d;best={type:'wild',w};} }
282:     for(const n of this.world.npcs){ const d=Math.hypot(n.x-wx,n.y-wy); if(d<bd){bd=d;best={type:'npc',n};} }
283:     if(best?.type==='wild') this.startWildBattle(best.w);
284:     else if(best?.type==='npc') this.talkNpc(best.n);
285:   }
