287:   /* ---------------- main loop ---------------- */
288:   loop(now){
289:     const dt=Math.min(.05,Math.max(0,(now-this.lastUpdate)/1000)); this.lastUpdate=now;
290:     if(!this.paused&&!this.modalOpen&&!this.battle.active) this.update(dt,now);
291:     else this.updateAmbient(dt,now);
292:     this.render(now);
293:     if(now-this.lastMinimap>120){ this.world.drawMinimap($('#minimap'),this,now); this.lastMinimap=now; }
294:     if(now-this.lastHud>1400){ this.updateHud(); this.lastHud=now; }
295:     if(now-this.lastSave>12000){ this.save(); this.lastSave=now; }
296:     if(now-this.lastChat>22000){ this.botChat(); this.lastChat=now; }
297:     if(now-this.lastPrompt>90){ this.updateInteraction(); this.lastPrompt=now; }
298:     requestAnimationFrame(t=>this.loop(t));
299:   }
