301:   update(dt,now){
302:     this.player.playtime=(this.player.playtime||0)+dt;
303:     this.clock+=dt*.22;
304:     if(this.clock>=1440) this.clock-=1440;
305:     this.updatePlayer(dt,now);
306:     this.updateCamera(dt);
307:     this.updateWilds(dt,now);
308:     this.updateBots(dt);
309:     this.updateParticles(dt);
310:     this.pruneRemotes(now);
311:     this.checkZone();
312:     this.updateEventTimer();
313:     if(Math.random()<dt*.18) this.remoteState();
314:     this.renderEventTimer();
315:   }
