317:   updateAmbient(dt,now){
318:     this.clock+=dt*.22;
319:     this.updateParticles(dt);
320:     this.updateCamera(dt,true);
321:     this.pruneRemotes(now);
322:     this.updateBots(dt*.35);
323:     this.updateEventTimer();
324:     this.renderEventTimer();
325:   }
