327:   updatePlayer(dt,now){
328:     let dx=0,dy=0;
329:     if(this.keys.has('a')||this.keys.has('arrowleft')) dx-=1;
330:     if(this.keys.has('d')||this.keys.has('arrowright')) dx+=1;
331:     if(this.keys.has('w')||this.keys.has('arrowup')) dy-=1;
332:     if(this.keys.has('s')||this.keys.has('arrowdown')) dy+=1;
333:     if(this.touch.active){ dx+=this.touch.x; dy+=this.touch.y; }
334:     const len=Math.hypot(dx,dy);
335:     if(len>.12){
336:       dx/=Math.max(1,len); dy/=Math.max(1,len);
337:       const sprint=(this.keys.has('shift')||Math.hypot(this.touch.x,this.touch.y)>.86)?1.55:1;
338:       const speed=4.55*sprint;
339:       const nx=this.player.x+dx*speed*dt;
340:       const ny=this.player.y+dy*speed*dt;
341:       if(this.world.isWalkable(nx,this.player.y)) this.player.x=nx;
342:       if(this.world.isWalkable(this.player.x,ny)) this.player.y=ny;
343:       this.player.moving=true;
344:       if(Math.abs(dx)>Math.abs(dy)) this.player.dir=dx>0?'right':'left';
345:       else this.player.dir=dy>0?'down':'up';
346:       this.player.frame=Math.floor(now/125)%4;
347:       if(Math.random()<dt*7) this.audio.chirp();
348:     } else {
349:       this.player.moving=false; this.player.frame=0;
350:     }
351:   }
