353:   updateCamera(dt,instant=false){
354:     const targetX=clamp(this.player.x*T-this.vw/2,0,MAP_W*T-this.vw);
355:     const targetY=clamp(this.player.y*T-this.vh/2,0,MAP_H*T-this.vh);
356:     if(instant||!this.cam.ready){ this.cam.x=targetX; this.cam.y=targetY; this.cam.ready=true; }
357:     else {
358:       const k=1-Math.pow(.0008,dt);
359:       this.cam.x+=(targetX-this.cam.x)*k;
360:       this.cam.y+=(targetY-this.cam.y)*k;
361:     }
362:   }
