382:   /* ---------------- world life ---------------- */
383:   spawnWilds(initial=false){
384:     const target=initial?28:28;
385:     let guard=0;
386:     while(this.wilds.length<target&&guard++<90){
387:       let zone=this.zone.id==='hollow'?ZONE_BY_ID.meadow:this.zone;
388:       if(Math.random()<.16) zone=pick(ZONES.filter(z=>z.id!=='hollow'&&z.id!==this.zone.id));
389:       let x=this.player.x+rand(-16,16), y=this.player.y+rand(-13,13);
390:       let tries=0;
391:       while(tries++<18&&(!this.world.isWalkable(x,y)||this.world.zoneAt(x,y).id==='hollow'||Math.hypot(x-this.player.x,y-this.player.y)<3.4)){
392:         x=this.player.x+rand(-17,17); y=this.player.y+rand(-13,13);
393:       }
394:       if(tries>=18) continue;
395:       if(this.wilds.some(w=>Math.hypot(w.x-x,w.y-y)<1.5)) continue;
396:       const spawn=biomeSpawns(zone,this.data,1,this.player.level)[0];
397:       if(!spawn) continue;
398:       const base=this.data[spawn.id-1];
399:       this.wilds.push({...spawn,x,y,name:base.name,dir:pick(['left','right','up','down']),phase:Math.random()*6.28,vx:0,vy:0,turnAt:performance.now()+rand(1000,5000),wander:true});
400:       this.getSprite(spawn.id);
401:     }
402:     // Keep the herd from becoming stale.
403:     const now=performance.now();
404:     this.wilds=this.wilds.filter(w=>{
405:       const d=Math.hypot(w.x-this.player.x,w.y-this.player.y);
406:       if(d>31&&this.wilds.length>8) return false;
407:       return now-w.turnAt<30000||true;
408:     });
409:   }
