413:     for(const [id,level,x,y] of critters){
414:       if(!this.world.isWalkable(x,y)) continue;
415:       const base=this.data[id-1];
416:       this.wilds.push({id,level,shiny:id===133&&Math.random()<.35,x,y,name:base.name,dir:pick(['left','right','up','down']),phase:Math.random()*6.28,vx:0,vy:0,turnAt:performance.now()+rand(1000,5000),wander:true,town:true});
