421:   updateWilds(dt,now){
422:     for(const w of this.wilds){
423:       const d=Math.hypot(w.x-this.player.x,w.y-this.player.y);
424:       if(d>33) continue;
425:       if(now>w.turnAt){
426:         w.turnAt=now+rand(2200,6500);
427:         if(Math.random()<.58){ const a=Math.random()*6.28; w.vx=Math.cos(a)*.28; w.vy=Math.sin(a)*.28; w.dir=Math.abs(w.vx)>Math.abs(w.vy)?(w.vx>0?'right':'left'):(w.vy>0?'down':'up'); }
428:         else { w.vx=0; w.vy=0; w.dir=pick(['left','right','up','down']); }
429:       }
430:       if(w.vx||w.vy){
431:         const nx=w.x+w.vx*dt, ny=w.y+w.vy*dt;
432:         if(this.world.isWalkable(nx,ny)){ w.x=nx; w.y=ny; }
433:         else { w.vx*=-1; w.vy*=-1; }
434:       }
435:       if(d<2.2&&Math.random()<dt*2){ w.dir=Math.abs(this.player.x-w.x)>Math.abs(this.player.y-w.y)?(this.player.x>w.x?'right':'left'):(this.player.y>w.y?'down':'up'); }
436:     }
437:     this.spawnWilds(false);
438:   }
