440:   spawnBots(){
441:     const points=[['hollow',76.6,66.4],['hollow',71.4,65.6],['hollow',82.2,64.4],['meadow',77,84],['meadow',70,86],['forest',47,65],['forest',42,58],['lake',97,62],['lake',102,65],['coast',128,77],['volcano',110,86],['snow',53,31],['swamp',78,98],['peak',76,36]];
442:     const leads=[25,133,906,935,448,658,778,745,887,887,1007,282,94,384];
443:     this.bots=points.map(([zone,x,y],i)=>{
444:       const z=ZONE_BY_ID[zone];
445:       if(!this.world.isWalkable(x,y)){ x+=rand(-2,2); y+=rand(-2,2); }
446:       return {
447:         id:'bot-'+i, name:TRAINER_NAMES[i%TRAINER_NAMES.length], level:8+Math.floor(rand(0,26)),
448:         title:TITLES[i%TITLES.length], x,y, homeX:x, homeY:y, zone:z.name, lead:leads[i%leads.length],
449:         palette:PALETTES[i%PALETTES.length], dir:pick(['down','left','right','up']), frame:0,
