455:   updateBots(dt){
456:     const now=performance.now();
457:     for(const b of this.bots){
458:       if(Math.hypot(b.x-this.player.x,b.y-this.player.y)>26){ b.frame=0; continue; }
459:       if(now>b.nextTurn){
460:         b.nextTurn=now+rand(2600,7200);
461:         const a=Math.random()*6.28;
462:         b.targetX=b.homeX+Math.cos(a)*rand(1,6);
463:         b.targetY=b.homeY+Math.sin(a)*rand(1,5);
464:       }
465:       const dx=b.targetX-b.x, dy=b.targetY-b.y, d=Math.hypot(dx,dy);
466:       if(d>.25){
467:         const sp=.85;
468:         const nx=b.x+dx/d*sp*dt, ny=b.y+dy/d*sp*dt;
469:         if(this.world.isWalkable(nx,ny)){ b.x=nx; b.y=ny; b.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'); b.frame=Math.floor(now/160)%4; }
470:         else { b.nextTurn=0; }
471:       } else b.frame=0;
472:     }
473:   }
