479:   /* ---------------- particles & render ---------------- */
480:   initParticles(){
481:     const biome=this.zone?.biome||'meadow';
482:     const count=this.vw<700?32:64;
483:     this.particles=[];
484:     for(let i=0;i<count;i++){
485:       const type=biome==='snow'?'snow':biome==='volcano'?'ember':biome==='swamp'?'firefly':biome==='forest'?'leaf':biome==='coast'?'spray':'pollen';
486:       this.particles.push({type,x:Math.random()*this.vw,y:Math.random()*this.vh,vx:rand(-6,6),vy:type==='snow'?rand(10,24):type==='ember'?rand(-18,-6):rand(-5,5),size:rand(1,3),phase:Math.random()*6.28,alpha:rand(.2,.7)});
487:     }
488:   }
489: 
490:   updateParticles(dt){
491:     for(const p of this.particles){
492:       p.x+=p.vx*dt; p.y+=p.vy*dt;
493:       if(p.type==='pollen') p.x+=Math.sin(performance.now()*.0006+p.phase)*.15;
494:       if(p.x<-10)p.x=this.vw+10; if(p.x>this.vw+10)p.x=-10;
495:       if(p.y<-10)p.y=this.vh+10; if(p.y>this.vh+10)p.y=-10;
496:     }
497:   }
