499:   render(now){
500:     const ctx=this.ctx;
501:     ctx.setTransform(this.dpr,0,0,this.dpr,0,0);
502:     ctx.clearRect(0,0,this.vw,this.vh);
503:     this.world.draw(ctx,this,this.cam,this.vw,this.vh,now);
504:     ctx.setTransform(this.dpr,0,0,this.dpr,0,0);
505:     if(this.settings.particles) this.drawParticles(ctx);
506:     this.drawLighting(ctx);
507:   }
508: 
509:   drawParticles(ctx){
510:     for(const p of this.particles){
511:       const pulse=.6+Math.sin(performance.now()*.002+p.phase)*.4;
512:       if(p.type==='pollen'){ ctx.fillStyle=`rgba(240,238,170,${p.alpha*.65})`; ctx.beginPath(); ctx.arc(p.x,p.y,p.size*.7,0,6.28); ctx.fill(); }
513:       else if(p.type==='snow'){ ctx.fillStyle=`rgba(248,253,255,${p.alpha})`; ctx.beginPath(); ctx.arc(p.x,p.y,p.size,0,6.28); ctx.fill(); }
514:       else if(p.type==='ember'){ ctx.fillStyle=`rgba(255,150,64,${p.alpha*pulse})`; ctx.beginPath(); ctx.arc(p.x,p.y,p.size*.8,0,6.28); ctx.fill(); }
515:       else if(p.type==='firefly'){ ctx.fillStyle=`rgba(206,255,127,${p.alpha*pulse})`; ctx.shadowColor='#c9f46c'; ctx.shadowBlur=8; ctx.beginPath(); ctx.arc(p.x,p.y,p.size*.8,0,6.28); ctx.fill(); ctx.shadowBlur=0; }
516:       else if(p.type==='leaf'){ ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(now*.001+p.phase); ctx.fillStyle=`rgba(167,205,101,${p.alpha*.6})`; ctx.fillRect(-p.size,-p.size*.5,p.size*2,p.size); ctx.restore(); }
517:       else if(p.type==='spray'){ ctx.fillStyle=`rgba(204,238,240,${p.alpha*.4})`; ctx.fillRect(p.x,p.y,p.size*1.5,p.size*.6); }
518:     }
519:   }
