521:   drawLighting(ctx){
522:     if(!this.settings.dayNight) return;
523:     const hour=(this.clock/60)%24;
524:     let tint=null, alpha=0;
525:     if(hour>17.5&&hour<20){ tint='rgba(255,142,69,'; alpha=(hour-17.5)/2.5*.15; }
526:     else if(hour>20||hour<5){ tint='rgba(22,42,83,'; alpha=.26; }
