623:   addTrainerXp(amount){
624:     this.player.xp=(this.player.xp||0)+amount;
625:     let need=2500+this.player.level*220;
626:     let leveled=false;
627:     while(this.player.xp>=need){
628:       this.player.xp-=need; this.player.level++; leveled=true;
629:       need=2500+this.player.level*220;
630:     }
631:     this.quests.main.level=this.player.level;
632:     if(leveled){
633:       this.toast(`Trainer level ${this.player.level}!`,'New field rank unlocked. Your team feels inspired.','gold');
634:       this.audio.sfx('level');
635:     }
636:     this.updateHud();
637:   }
