639:   addXp(mon,amount){
640:     const gains=[];
641:     mon.xp+=amount;
642:     mon.xpNext=xpToNext(mon.level);
643:     while(mon.xp>=mon.xpNext&&mon.level<100){
644:       mon.xp-=mon.xpNext; mon.level++; gains.push(mon.level);
645:       const oldMax=mon.maxHp;
646:       const fresh=createMon(mon.id,mon.level,this.data);
647:       mon.stats=fresh.stats; mon.maxHp=fresh.maxHp;
648:       mon.hp=Math.min(mon.maxHp,mon.hp+(mon.maxHp-oldMax));
649:       mon.moves=fresh.moves;
650:       mon.xpNext=xpToNext(mon.level);
651:       this.dex.seen.add(mon.id);
652:     }
653:     if(gains.length){
654:       this.toast(`${mon.name} reached Lv.${mon.level}!`,`+${gains.length} level${gains.length>1?'s':''} · stats increased`,'gold');
655:       const evolved=this.evolveIfReady(mon);
656:       if(evolved) setTimeout(()=>this.toast(`${evolved.from} evolved!`,`Say hello to ${evolved.to}.`,'purple'),800);
657:     }
658:     this.updateHud(); this.renderParty();
659:     return gains;
660:   }
661: 
662:   evolveIfReady(mon){
663:     const levelReq=mon.base.evolve;
664:     const targets=this.evoMap[mon.id];
665:     if(!levelReq||!targets||!targets.length||mon.level<levelReq) return null;
666:     const target=targets[0];
667:     const oldName=mon.name;
668:     const fresh=createMon(target.id,mon.level,this.data);
669:     mon.id=target.id; mon.name=target.name; mon.types=target.types; mon.base=target;
670:     mon.stats=fresh.stats; mon.maxHp=fresh.maxHp; mon.hp=Math.min(mon.maxHp,mon.hp+Math.round(fresh.maxHp*.25));
671:     mon.moves=fresh.moves;
672:     this.dex.caught.add(target.id); this.dex.seen.add(target.id);
673:     this.getSprite(target.id);
674:     this.updateHud(); this.renderParty();
675:     return {from:oldName,to:target.name};
676:   }
