220:   playerMove(i){
221:     if(!this.active||this.busy) return;
222:     const move=this.ally.moves[i];
223:     if(!move||move.pp<=0) return;
224:     this.busy=true;
225:     move.pp--;
226:     this.renderMoves();
227:     this.log(`${this.ally.name} used ${move.name}!`);
228:     const result=calcDamage(this.ally,this.enemy,move,this.game.data);
229:     this.animateHit('enemy',result,move);
230:     setTimeout(()=>{
231:       if(!this.active) return;
232:       if(result.miss){ this.log(`${this.ally.name}’s attack missed!`); this.afterPlayerAction(); return; }
233:       this.enemy.hp=Math.max(0,this.enemy.hp-result.dmg);
234:       this.updateHud();
235:       if(result.mult===0) this.log('It had no effect...');
236:       else if(result.crit) this.log(`A critical hit! ${result.dmg} damage.`);
237:       else if(result.mult>1) this.log(`It’s super effective! ${result.dmg} damage.`);
238:       else if(result.mult<1) this.log(`It’s not very effective... ${result.dmg} damage.`);
239:       else this.log(`${this.enemy.name} took ${result.dmg} damage.`);
240:       this.game.audio.sfx(result.mult>1?'super':'hit');
241:       if(this.enemy.hp<=0) setTimeout(()=>this.enemyFainted(),500);
242:       else this.afterPlayerAction();
243:     },520);
244:   }
