254:   enemyTurn(){
255:     if(!this.active||this.enemy.hp<=0) return;
256:     this.busy=true;
257:     const moves=this.enemy.moves.filter(m=>m.pp>0);
258:     if(!moves.length){ this.busy=false; return; }
259:     let move=pick(moves);
260:     const superMoves=moves.filter(m=>typeEffect(m.type,this.ally.types)>1);
261:     if(superMoves.length&&Math.random()<.55) move=pick(superMoves);
262:     move.pp--;
263:     setTimeout(()=>{
264:       if(!this.active) return;
265:       this.log(`${this.enemy.name} used ${move.name}!`);
266:       const result=calcDamage(this.enemy,this.ally,move,this.game.data);
267:       this.animateHit('ally',result,move);
268:       setTimeout(()=>{
269:         if(!this.active) return;
270:         if(result.miss){ this.log(`${this.enemy.name}’s attack missed!`); this.finishTurn(); return; }
271:         this.ally.hp=Math.max(0,this.ally.hp-result.dmg);
272:         this.updateHud();
273:         if(result.mult>1) this.log(`It’s super effective! ${this.ally.name} took ${result.dmg} damage.`);
274:         else if(result.mult<1&&result.mult>0) this.log(`It’s not very effective... ${result.dmg} damage.`);
275:         else this.log(`${this.ally.name} took ${result.dmg} damage.`);
276:         this.game.audio.sfx('hit');
277:         if(this.ally.hp<=0) setTimeout(()=>this.allyFainted(),600);
278:         else this.finishTurn();
279:       },520);
280:     },650);
281:   }
