325:   attemptCatch(ballKey='pokeball'){
326:     if(!this.active||this.busy||this.trainer||this.raid) return;
327:     if(!this.game.bag[ballKey]) return;
328:     this.busy=true;
329:     this.game.bag[ballKey]--; this.game.updateHud();
330:     const ball=ITEMS[ballKey];
331:     this.log(`You threw a ${ball.name}!`);
332:     this.game.audio.sfx('throw');
333:     const ov=this.root.querySelector('#catchOverlay');
334:     ov.querySelector('.catch-ball').style.background=ballKey==='greatball'?'linear-gradient(180deg,#5b9cff 0 45%,#1b241f 46% 54%,#f4f7ef 55%)':ballKey==='ultraball'?'linear-gradient(180deg,#ffd54d 0 45%,#1b241f 46% 54%,#f4f7ef 55%)':'';
335:     ov.classList.add('show');
336:     const label=ov.querySelector('#catchLabel');
337:     const chance=catchChance(this.enemy,ball.catch);
338:     const success=Math.random()<chance;
339:     label.textContent='1...';
340:     setTimeout(()=>label.textContent='2...',650);
341:     setTimeout(()=>label.textContent='3...',1250);
342:     setTimeout(()=>{
343:       ov.classList.remove('show');
344:       if(success){
345:         this.game.audio.sfx('catch');
346:         this.log(`Gotcha! ${this.enemy.name.replace('✦ ','')} was caught!`);
347:         setTimeout(()=>this.catchSuccess(),650);
348:       } else {
349:         this.game.audio.sfx('flee');
350:         this.log(`Oh no! ${this.enemy.name} broke free!`);
351:         this.busy=false;
352:         setTimeout(()=>{ if(this.active) this.enemyTurn(); },600);
353:       }
354:     },1900);
355:   }
