357:   catchSuccess(){
358:     if(!this.active) return;
359:     const mon=this.enemy;
360:     const res=this.game.onCatch(mon,this.wild);
361:     this.showResult('caught',{
362:       title:`${mon.name.replace('✦ ','')} was caught!`,
363:       desc:res.partyFull?'Your party is full, so your new friend was sent to the reserve box.':'A new friend joined your party. The Pokédex has been updated.',
364:       stats:[['LEVEL',mon.level],['DEX',`#${String(mon.id).padStart(4,'0')}`],['HP',`${mon.hp}/${mon.maxHp}`]],
365:       sprite:mon.id
366:     });
367:   }
