369:   enemyFainted(){
370:     if(!this.active) return;
371:     this.game.audio.sfx('level');
372:     if(this.trainer&&this.enemyIndex<this.enemyTeam.length-1){
373:       this.enemyIndex++;
374:       this.enemy=this.enemyTeam[this.enemyIndex];
375:       this.log(`${this.trainer.name} sent out ${this.enemy.name}!`);
376:       this.updateHud(); this.renderMoves();
377:       setTimeout(()=>{ this.busy=false; this.log('What will you do?'); },800);
378:       return;
379:     }
380:     const xp=Math.floor((this.enemy.level*7+this.enemy.base.atk*.35+this.enemy.base.hp*.25)*(this.trainer?1.35:1));
381:     const gains=this.game.addXp(this.ally,xp);
382:     this.game.audio.sfx('level');
383:     if(this.raid){ this.game.onRaidWin(); }
384:     if(this.trainer){
385:       const prize=350+this.game.player.level*35;
386:       this.game.player.coins+=prize;
387:       this.game.onTrainerWin(this.trainer,prize);
388:     }
389:     this.game.questEvent('battleWin',{enemy:this.enemy});
390:     this.game.updateHud();
391:     const stats=[['XP',`+${xp}`],['LEVEL',`${this.ally.level}`]];
392:     if(gains.length) stats.push(['LEVEL UP',`+${gains.length}`]);
393:     this.showResult('win',{
394:       title:this.trainer?`${this.trainer.name} defeated!`:'Victory!',
395:       desc:this.trainer?`You earned ${350+this.game.player.level*35} coins and ${xp} XP.`:`${this.ally.name} earned ${xp} XP. The wilds grow quiet again.`,
396:       stats,sprite:this.enemy.id
397:     });
398:   }
