418:   tryRun(silent=false){
419:     if(!this.active||this.busy) return;
420:     if(this.trainer){ this.log('There’s no running from a trainer battle!'); return; }
421:     const chance=.52+this.ally.stats.spe/(this.enemy.stats.spe*2.2);
