469:     if(e.key>='1'&&e.key<='4'){ this.playerMove(Number(e.key)-1); e.preventDefault(); }
470:     else if(e.key.toLowerCase()==='c'){ this.openBag('balls'); e.preventDefault(); }
471:     else if(e.key.toLowerCase()==='r'){ this.tryRun(); e.preventDefault(); }
472:     else if(e.key.toLowerCase()==='b'){ this.openBag('items'); e.preventDefault(); }
