content.text:
101:.rank-tag{font-family:var(--pixel);font-size:7px;padding:4px 5px;border-radius:4px;background:rgba(201,244,108,.13);color:var(--lime);border:1px solid rgba(201,244,108,.22);letter-spacing:.5px}
492:.settings-list{display:flex;flex-direction:column;gap:8px}
493:.setting-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 12px;border-radius:9px;background:rgba(255,255,255,.03);border:1px solid var(--line)}
494:.setting-row strong{font-size:9.5px;display:block}
495:.setting-row p{font-size:7.5px;color:var(--dim);margin:2px 0 0}
496:.toggle{width:35px;height:20px;border-radius:20px;background:rgba(255,255,255,.1);position:relative;flex:none;transition:.2s}
497:.toggle::after{content:'';position:absolute;left:3px;top:3px;width:14px;height:14px;border-radius:50%;background:#8da197;transition:.2s}
