import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await page.waitForTimeout(1200);

const read = async () => page.evaluate(() => ({
  lang: localStorage.getItem('terraverse_lang'),
  zone: document.querySelector('#zoneName')?.textContent,
  quest: document.querySelector('#questTitle')?.textContent,
  questObj: document.querySelector('#questObj2 span:nth-child(2)')?.textContent,
  chatTab: document.querySelector('[data-chat="global"]')?.textContent,
  hint: document.querySelector('.control-hint')?.textContent.trim().replace(/\s+/g,' '),
  partyTitle: document.querySelector('#partyRail')?.parentElement?.querySelector('.head-title')?.textContent.trim(),
  langBtn: document.querySelector('#btnLang')?.textContent,
  docLang: document.documentElement.lang,
  title: document.title
}));

console.log('EN state:', JSON.stringify(await read(), null, 1));

await page.click('#btnLang');
await page.waitForTimeout(700);
console.log('FR state:', JSON.stringify(await read(), null, 1));

// Settings panel in French
await page.click('#btnSettings');
await page.waitForTimeout(400);
const settings = await page.evaluate(() => ({
  title: document.querySelector('.modal-head h2, .modal-title, .modal h2')?.textContent,
  rows: [...document.querySelectorAll('.setting-row strong')].map(e => e.textContent),
  langChoices: [...document.querySelectorAll('.lang-choice')].map(e => e.textContent + (e.classList.contains('active')?'*':''))
}));
console.log('settings FR:', JSON.stringify(settings));
await page.screenshot({ path: '/tmp/opencode/fr-settings.jpg', type: 'jpeg', quality: 60 });
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// Dex in French
await page.click('[data-slot="dex"]');
await page.waitForTimeout(500);
const dex = await page.evaluate(() => ({
  title: document.querySelector('.modal-head h2, .modal h2')?.textContent,
  first: [...document.querySelectorAll('.dex-card strong')].slice(0,3).map(e=>e.textContent),
  stats: [...document.querySelectorAll('.dex-stat span')].map(e=>e.textContent),
  chips: [...document.querySelectorAll('.gen-chip')].slice(0,3).map(e=>e.textContent)
}));
console.log('dex FR:', JSON.stringify(dex));
await page.screenshot({ path: '/tmp/opencode/fr-dex.jpg', type: 'jpeg', quality: 60 });
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// Tutorial via settings
await page.click('#btnSettings');
await page.waitForTimeout(300);
await page.click('#openGuide');
await page.waitForTimeout(400);
const tut = await page.evaluate(() => ({
  title: [...document.querySelectorAll('.modal h2, .modal-title')].map(e=>e.textContent),
  story: document.querySelector('.tutorial-story h3')?.textContent,
  steps: [...document.querySelectorAll('.tutorial-step strong')].map(e=>e.textContent),
  controls: document.querySelector('.tutorial-controls')?.textContent
}));
console.log('tutorial FR:', JSON.stringify(tut));
await page.screenshot({ path: '/tmp/opencode/fr-tutorial.jpg', type: 'jpeg', quality: 60 });
await page.click('#tutorialStart').catch(()=>{});
await page.waitForTimeout(300);

// switch back to EN and verify persisted
await page.click('#btnLang');
await page.waitForTimeout(600);
console.log('EN again:', JSON.stringify(await read(), null, 1));

// reload, ensure persisted EN and no errors
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await page.waitForTimeout(1000);
console.log('after reload:', JSON.stringify(await read(), null, 1));

console.log('ERRORS:', errors);
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await page.waitForTimeout(1000);
// switch to FR
await page.click('#btnLang');
await page.waitForTimeout(600);

// start a wild battle
await page.evaluate(() => { const g=window.terraverse; g.startWildBattle(g.wilds[0]); });
await page.waitForTimeout(900);
const battle = await page.evaluate(() => ({
  mode: document.querySelector('.battle-mode')?.textContent.trim(),
  log: document.querySelector('.battle-log')?.textContent.trim(),
  enemy: document.querySelector('#enemyName')?.textContent,
  enemyLv: document.querySelector('#enemyLv')?.textContent,
