import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await page.waitForTimeout(800);
await page.click('#btnLang'); await page.waitForTimeout(500);
// social titles FR
await page.evaluate(() => window.terraverse.openSocial()); await page.waitForTimeout(400);
console.log('social titles FR:', await page.evaluate(() => [...document.querySelectorAll('.sp-info > span')].slice(0,6).map(e=>e.textContent)));
await page.keyboard.press('Escape'); await page.waitForTimeout(300);
// settings language switch via panel
await page.click('#btnSettings'); await page.waitForTimeout(400);
await page.click('[data-lang="en"]'); await page.waitForTimeout(600);
console.log('settings after EN:', await page.evaluate(() => ({
  active: document.querySelector('.lang-choice.active')?.textContent,
  rows: [...document.querySelectorAll('.setting-row strong')].map(e=>e.textContent),
  lang: localStorage.getItem('terraverse_lang'),
  zone: document.querySelector('#zoneName')?.textContent
})));
await page.click('[data-lang="fr"]'); await page.waitForTimeout(600);
console.log('settings after FR:', await page.evaluate(() => ({
  active: document.querySelector('.lang-choice.active')?.textContent,
  rows: [...document.querySelectorAll('.setting-row strong')].map(e=>e.textContent),
  lang: localStorage.getItem('terraverse_lang'),
  zone: document.querySelector('#zoneName')?.textContent
})));
await page.screenshot({ path: '/tmp/opencode/fr-settings2.jpg', type: 'jpeg', quality: 60 });
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
// mobile screenshot FR
const mob = await browser.newPage({ viewport: { width: 390, height: 844 } });
mob.on('pageerror', e => errors.push('MOBILE PAGEERROR ' + e.message));
await mob.goto('http://localhost:3000/', { waitUntil: 'load' });
await mob.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await mob.waitForTimeout(1200);
console.log('mobile FR:', await mob.evaluate(() => ({ lang: localStorage.getItem('terraverse_lang'), zone: document.querySelector('#zoneName')?.textContent, langBtn: document.querySelector('#btnLang')?.textContent, quest: document.querySelector('#questTitle')?.textContent })));
await mob.screenshot({ path: '/tmp/opencode/fr-mobile.jpg', type: 'jpeg', quality: 60 });
// reload desktop and verify persistence
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.terraverse && document.documentElement.classList.contains('ready'), null, { timeout: 30000 });
await page.waitForTimeout(900);
console.log('persisted:', await page.evaluate(() => ({ lang: localStorage.getItem('terraverse_lang'), zone: document.querySelector('#zoneName')?.textContent, title: document.title, htmlLang: document.documentElement.lang })));
console.log('ERRORS:', errors);
await browser.close();

